1	// Cyrus Test Flight (R0) types: the typed spec a caller writes, the resolved spec the node-2 runner receives,
2	// and the report it returns. The runner is services/modbuilder/tools/testflight/runner.js (plain Node on node-2).
3	// A check passes only if it actually ran; a skipped required check means the flight is NOT a success.
4	import type { PlaytestPlan } from "../playtest/plan";
5	import type { StressSpec } from "./stress";
6	import type { WorldgenSpec } from "./worldgen";
7	
8	export const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "worldgen", "playtest", "stress", "clean_stop", "no_leaks"] as const;
9	export type CheckId = (typeof CHECK_IDS)[number];
10	export type CheckStatus = "pass" | "fail" | "not_run";
11	
12	/** A regex matched against each log line (JS syntax; flags limited to i/m/s/u). */
13	export type LogMatcher = { id: string; pattern: string; flags?: string };
14	
15	/** A small text file in the server directory (e.g. a plugin's config). Path relative to the server root, under plugins/ only. */
16	export type ServerFile = { path: string; content: string };
17	
18	export type SeedRef = { from: string; to: string };
19	
20	export type RconCheck = {
21	  id?: string;
22	  /** Written (created or replaced) in the server dir right before this command is sent, e.g. to test a config reload. */
23	  writeFile?: ServerFile;
24	  /** Wait this long (ms, max 30000) before sending the command (after writeFile), e.g. for a file watcher. */
25	  waitMs?: number;
26	  /** One console command without the leading slash. stop/restart/op/deop/reload are reserved for the runner. */
27	  command: string;
28	  /** Every substring must appear in the reply (colour codes stripped). Empty = the command only has to answer. */
29	  expect?: string[];
30	  /** None of these may appear. */
31	  expectNot?: string[];
32	  /** Default true. An optional check is reported but does not fail the stage. */
33	  required?: boolean;
34	};
35	
36	/** An artifact either on the caller's disk (uploaded by the invoker) or already on node-2 under the Test Flight root. */
37	export type ArtifactRef = { localPath: string; remotePath?: never; sha256?: string } | { remotePath: string; localPath?: never; sha256?: string };
38	
39	export type TestFlightSpec = {
40	  /** Exact registry id, e.g. "26.2" or "1.21.11". The registry supplies the JDK and the pinned Paper server jar. */
41	  version: string;
42	  plugins?: ArtifactRef[];
43	  /** Datapacks go into world/datapacks before first boot; each one adds an automatic `datapack list enabled` check. */
44	  datapacks?: (ArtifactRef & { name: string })[];
45	  /** Written to server.properties only. No client connects, so the pack itself is NOT exercised (reported as such). */
46	  resourcePack?: { url: string; sha1?: string; id?: string; required?: boolean };
47	  /** Small text files placed before the first boot (max 16, 64 KB each, under plugins/). */
48	  files?: ServerFile[];
49	  /**
50	   * Read-only directories prepared on node-2 under `<root>/seeds/<from>` copied into the server dir before boot
51	   * (`to` = "libraries" or a path under plugins/). The flight has no internet, so a managed plugin's pinned runtime
52	   * libraries are seeded this way (runner tf-lite-2).
53	   */
54	  seeds?: SeedRef[];
55	  /** Server-dir files copied out after the stop to `<root>/collect/<runId>/` (a path ending in "/" = a listing). */
56	  collect?: string[];
57	  rcon?: RconCheck[];
58	  /** Replace the runner's default startup-log matchers (omit to use the defaults). */
59	  logMatchers?: LogMatcher[];
60	  /** Extra ignore patterns, added to the runner's sandbox ignores. */
61	  logIgnore?: LogMatcher[];
62	  timeouts?: { bootSec?: number; rconSec?: number; stopSec?: number; totalSec?: number };
63	  /** xmxMb max 1024 (node-2 rule). rssCapMb is a watchdog: above it the server is killed and the run fails. */
64	  memory?: { xmxMb?: number; rssCapMb?: number };
65	  /** Extra stages to treat as required even if the spec would not make them required. */
66	  requireStages?: CheckId[];
67	  /** Keep the server dir on node-2 for debugging (default false). */
68	  keepDir?: boolean;
69	  /** World options (runner tf-lite-3): generateStructures turns structure generation on (default off: a tiny flat world). */
70	  world?: { generateStructures?: boolean };
71	  /** Playtest (runner tf-lite-4): a scripted Mineflayer player runs these scenarios after the RCON checks. Makes `playtest` required. */
72	  playtest?: PlaytestPlan;
73	  /** Stress (runner tf-lite-5, perf safety): scripted load after the boot checks while the real TPS is sampled. Makes `stress` required. */
74	  stress?: StressSpec;
75	  /** Worldgen density probes (runner tf-lite-6): fill-replace counts in the pack's dimensions vs a stated range. Makes `worldgen` required. */
76	  worldgen?: WorldgenSpec;
77	};
78	
79	/** What the runner receives: registry pins resolved, artifact paths on node-2. */
80	export type ResolvedSpec = {
81	  schema: 1;
82	  runId: string;
83	  version: string;
84	  javaRelease: 21 | 25;
85	  paper: { build: number; sha256: string };
86	  plugins: { path: string; sha256?: string }[];
87	  datapacks: { path: string; name: string }[];
88	  resourcePack?: TestFlightSpec["resourcePack"];
89	  files?: ServerFile[];
90	  seeds?: SeedRef[];
91	  collect?: string[];
92	  rcon: RconCheck[];
93	  logMatchers?: LogMatcher[];
94	  logIgnore?: LogMatcher[];
95	  timeouts: { bootSec: number; rconSec: number; stopSec: number; totalSec: number };
96	  memory: { xmxMb: number; rssCapMb: number };
97	  keepDir: boolean;
98	  world?: { generateStructures?: boolean };
99	  playtest?: PlaytestPlan;
100	  stress?: StressSpec;
101	  worldgen?: WorldgenSpec;
102	};
103	
104	export type CheckResult = { id: CheckId; status: CheckStatus; required: boolean; evidence: string[]; durationMs: number };
105	
106	export type ReportArtifact =
107	  | { kind: "plugin"; file: string; sha256: string; pluginName: string | null; apiVersion: string | null; descriptor: string | null }
108	  | { kind: "datapack"; name: string; sha256: string | null; directory: boolean }
109	  | { kind: "resourcePack"; url: string; sha1: string | null; exercised: false }
110	  | { kind: "seed"; from: string; to: string; files: number; bytes: number; sha256: string };
111	
112	/** A collected server file (runner tf-lite-2) or a directory listing. */
113	export type CollectedItem = { path: string; kind?: "file" | "listing"; bytes?: number; sha256?: string; dest?: string; entries?: number; listing?: string[]; error?: string };
114	
115	export type EngineMeta = {
116	  runner: string;
117	  runnerSha256: string;
118	  node: string;
119	  host: string;
120	  kernel: string;
121	  jdk: { release: number; version: string | null; dist: string; sha256: string };
122	  paper: { version: string; build: number; sha256: string; channel: string | null };
123	  isolation: { netns: string; uid: number; noNewPrivs: boolean; nice: number; activeProcessorCount: number };
124	  /** Runner tf-lite-4, flights with a playtest: the pinned bot lockfile and the versions it was verified on. */
125	  bot?: { lockSha256: string; versions: string[] };
126	};
127	
128	/** Raw runner output. `status` says whether the runner itself completed; `overall` is its own verdict (recomputed by summarize). */
129	export type TestFlightReport = {
130	  schema: 1;
131	  runId: string | null;
132	  status: "completed" | "busy" | "error";
133	  version: string | null;
134	  javaRelease: number | null;
135	  startedAt: string;
136	  finishedAt: string | null;
137	  checks: CheckResult[];
138	  timings: Record<string, number>;
139	  bootMs: number | null;
140	  doneReportedSec: number | null;
141	  peakRssKb: number | null;
142	  artifacts: ReportArtifact[];
143	  engine: EngineMeta | null;
144	  notes: string[];
145	  overall: "passed" | "failed" | "incomplete";
146	  collected?: CollectedItem[];
147	  /** Runner tf-lite-4: the playtest bot's result (lib/cyrus/playtest/verdict.ts PlaytestRunResult). */
148	  playtest?: unknown;
149	  /** Runner tf-lite-5: the stress phase's samples + verdict (./stress.ts StressResult). */
150	  stress?: unknown;
151	  /** Runner tf-lite-6: the worldgen probes' results ({ schema, probes: ./worldgen.ts ProbeResult[] }). */
152	  worldgen?: unknown;
153	};
154	
155	export type Overall = "passed" | "failed" | "incomplete" | "busy" | "error";
156	
157	export type TestFlightSummary = {
158	  version: string;
159	  overall: Overall;
160	  /** true only when overall === "passed". */
161	  success: boolean;
162	  passed: CheckId[];
163	  failed: CheckId[];
164	  /** Required checks that did not run (or "passed" without evidence): any entry here blocks success. */
165	  skippedRequired: CheckId[];
166	  notRunOptional: CheckId[];
167	  reasons: string[];
168	  bootMs: number | null;
169	  peakRssKb: number | null;
170	  runId: string | null;
171	};
172	
173	export type MatrixSummary = { overall: Overall; success: boolean; versions: TestFlightSummary[] };
174	// Cyrus R5: the TEST FLIGHT GATE (pure half). After a build succeeds and scans clean, the worker boots it once on a
175	// disposable Paper server for the build's own version (node-2, ./client.ts) with its jar, its data packs and (when the
176	// Pack Loader jar is available) its pack config, and stores an HONEST per-check result on the build:
177	//   compile, scan, boot, plugins enabled, commands registered, data pack loaded  (each pass / fail / not_run)
178	// "not run" is never shown as passed; the verdict only ever feeds a "boot-tested on <version>" label (a boot proves
179	// the plugin loads and its commands register, never how it behaves in game). Optional: block publishing / installing a
180	// build whose flight FAILED (CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1).
181	// Flags (all OFF): CYRUS_TESTFLIGHT_GATE=1 runs flights; CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1 blocks on a failed flight.
182	// Limits: one flight at a time per worker (node-2 runs one anyway; "busy" is retried with backoff), at most
183	// MAX_FLIGHTS_PER_BUILD real flights per build (per-build cost cap) and MAX_BUSY_RETRIES busy retries.
184	import { getVersion } from "../versions/registry";
185	import type { CheckResult, RconCheck, TestFlightReport, TestFlightSpec, TestFlightSummary } from "./types";
186	import { stressBlocks, type StoredStress } from "./stress";
187	import type { StoredWorldgen } from "./worldgen";
188	
189	export const GATE_FLAG = "CYRUS_TESTFLIGHT_GATE";
190	export const BLOCK_FLAG = "CYRUS_TESTFLIGHT_BLOCK_ON_FAIL";
191	export const MAX_FLIGHTS_PER_BUILD = 2;
192	export const MAX_BUSY_RETRIES = 12;
193	export const MAX_COMMAND_CHECKS = 8;
194	export const GATE_VERSION = "tfgate-1";
195	
196	export const GATE_CHECKS = ["compile", "scan", "boot", "plugins_enabled", "commands_registered", "datapack_loaded"] as const;
197	export type GateCheckId = (typeof GATE_CHECKS)[number];
198	export type GateCheck = { id: GateCheckId; status: "pass" | "fail" | "not_run"; detail: string };
199	export type GateVerdict = "passed" | "failed" | "incomplete" | "not_run";
200	
201	/** What is stored on ModBuild.cyrus.testFlight (plain JSON, small). */
202	export type StoredFlight = {
203	  schema: 1;
204	  gate: string;
205	  state: "queued" | "running" | "done" | "not_run" | "gave_up";
206	  version: string;
207	  verdict: GateVerdict;
208	  /** "boot-tested on Paper <version>" only when every required check passed; never about in-game behaviour. */
209	  label: string | null;
210	  checks: GateCheck[];
211	  reason?: string;
212	  flights: number;
213	  busyRetries: number;
214	  nextAt?: string;
215	  lastError?: string;
216	  runId?: string | null;
217	  bootMs?: number | null;
218	  peakRssKb?: number | null;
219	  engine?: { runner?: string; paperBuild?: number; jdk?: string | null } | null;
220	  notes?: string[];
221	  /** Wiring 2 (CYRUS_PLAYTEST): the playtest bots' verdict from the build's stored ModSpec, kept APART from the boot
222	   *  verdict (a playtest never changes `verdict` / `label`). Absent = the switch was off. */
223	  playtest?: { verdict: "passed" | "failed" | "incomplete" | "not_run"; label: string; counts?: { planned: number; ran: number; passed: number; failed: number; notRun: number }; scenarios?: { id: string; status: string; reason: string | null }[]; specRevisionId?: string | null } | null;
224	  /** R42: the vanilla reference checks of the build's packs (copied from ModBuild.result.assets.vanilla). Never changes
225	   *  `verdict` / `label`: a pack that overrides vanilla still boots; this is a warning for the owner and the customer. */
226	  vanilla?: { status: "checked" | "not_run"; version: string; counts: { error: number; warn: number; info: number }; issues: { code: string; severity: string; path: string; message: string }[] } | null;
227	  /** Perf safety: the STRESS phase (./stress.ts storedStress), kept apart from the boot verdict. A FAILED stress blocks
228	   *  Install by default (flightBlocks). Absent = not flown (switch off or an older flight). */
229	  stress?: StoredStress | null;
230	  /** tf-lite-6 (CYRUS_TESTFLIGHT_WORLDGEN=1): worldgen density probes of the build's data packs (./worldgen.ts). Informational:
231	   *  never changes `verdict` / `label` and never blocks Install. Absent = switched off or no probe-able feature. */
232	  worldgen?: StoredWorldgen | null;
233	  at: string;
234	};
235	
236	export type GateBuild = {
237	  id: string; mcVersion: string; pluginName: string | null; jarSha256: string | null;
238	  /** ModBuild.result: commands + safety are read from it. */
239	  result: unknown;
240	};
241	export type GateArtifacts = {
242	  jarPath: string;
243	  /** spec + namespace (optional): the data pack spec it was built from, for the worldgen density probes. */
244	  datapacks: { name: string; localPath: string; spec?: unknown; namespace?: string }[];
245	  /** The Pack Loader jar + the packs.json this build's pack would get (when both are available). */
246	  packLoader?: { localPath: string; sha256: string; config: string } | null;
247	};
248	
249	/** Can this version be test-flown at all? (a pinned Paper SERVER build is needed). */
250	export function flightVersion(v: string): { ok: true } | { ok: false; reason: string } {
251	  const row = getVersion(v);
252	  if (!row) return { ok: false, reason: `not run: ${v} is not in the version registry` };
253	  if (!row.paperBuild || !row.paperServerSha256) return { ok: false, reason: `not run: no test server for ${v} (no pinned Paper server build)` };
254	  return { ok: true };
255	}
256	
257	type Cmd = { usage?: string };
258	/** Command labels the build says it has (from ModBuild.result.commands usage, e.g. "/alpha give <p>" -> alpha). */
259	export function commandLabels(result: unknown): string[] {
260	  const cmds = ((result as { commands?: Cmd[] } | null)?.commands ?? []) as Cmd[];
261	  const out: string[] = [];
262	  for (const c of cmds) {
263	    const m = /^\/([a-z0-9_-]{1,32})(?:\s|$)/i.exec(String(c?.usage ?? "").trim());
264	    if (m && !out.includes(m[1].toLowerCase())) out.push(m[1].toLowerCase());
265	  }
266	  return out.slice(0, MAX_COMMAND_CHECKS);
267	}
268	
269	export function scanVerdict(result: unknown): "pass" | "warn" | "block" | null {
270	  const v = (result as { safety?: { verdict?: string } | null } | null)?.safety?.verdict;
271	  return v === "pass" || v === "warn" || v === "block" ? v : null;
272	}
273	
274	/** The flight spec for one build, or why it is not run. */
275	export function planGateFlight(b: GateBuild, art: GateArtifacts): { ok: true; spec: TestFlightSpec; commands: string[] } | { ok: false; reason: string } {
276	  const fv = flightVersion(b.mcVersion);
277	  if (!fv.ok) return fv;
278	  if (!b.pluginName) return { ok: false, reason: "not run: the build has no plugin name" };
279	  const sv = scanVerdict(b.result);
280	  if (sv === "block") return { ok: false, reason: "not run: the safety scan blocked this build" };
281	  const commands = commandLabels(b.result);
282	  const rcon: RconCheck[] = [
283	    { id: "plugins", command: "plugins", expect: [b.pluginName] },
284	    // Paper answers `help <label>` with the command's help topic when it is registered, "No help for" otherwise
285	    ...commands.map((c) => ({ id: `cmd-${c}`, command: `help ${c}`, expectNot: ["No help for"], required: false })),
286	  ];
287	  const plugins: TestFlightSpec["plugins"] = [{ localPath: art.jarPath, ...(b.jarSha256 ? { sha256: b.jarSha256 } : {}) }];
288	  const files: TestFlightSpec["files"] = [];
289	  if (art.packLoader) {
290	    plugins.push({ localPath: art.packLoader.localPath, sha256: art.packLoader.sha256 });
291	    files.push({ path: "plugins/NxeonPackLoader/packs.json", content: art.packLoader.config });
292	    rcon.push({ id: "packs", command: "nxpacks status", expect: ["config=ok"], required: false });
293	  }
294	  return { ok: true, commands, spec: { version: b.mcVersion, plugins, datapacks: art.datapacks.map((d) => ({ name: d.name, localPath: d.localPath })), ...(files.length ? { files } : {}), rcon, timeouts: { bootSec: 180, totalSec: 420 } } };
295	}
296	
297	const check = (r: TestFlightReport, id: CheckResult["id"]) => r.checks.find((c) => c.id === id) ?? null;
298	const ev = (c: CheckResult | null, n = 2) => (c ? c.evidence.slice(0, n).join(" | ").slice(0, 300) : "");
299	
300	/** Map one flight to the six honest statuses. */
301	export function gateChecks(b: GateBuild, r: TestFlightReport | null, s: TestFlightSummary | null, o: { commands: string[]; datapacks: number; reason?: string }): GateCheck[] {
302	  const sv = scanVerdict(b.result);
303	  const nr = (id: GateCheckId, detail: string): GateCheck => ({ id, status: "not_run", detail });
304	  const out: GateCheck[] = [
305	    { id: "compile", status: "pass", detail: "compiled by the build service" },
306	    sv === null ? nr("scan", "no scan result stored") : { id: "scan", status: sv === "block" ? "fail" : "pass", detail: sv === "warn" ? "passed with warnings" : sv === "block" ? "blocked by the safety scan" : "clean" },
307	  ];
308	  if (!r || r.status !== "completed" || !s) {
309	    const why = o.reason ?? (r?.status === "busy" ? "not run: the test server was busy" : r ? `not run: ${r.status}` : "not run");
310	    return [...out, nr("boot", why), nr("plugins_enabled", why), nr("commands_registered", why), nr("datapack_loaded", o.datapacks ? why : "no data pack in this build")];
311	  }
312	  const boot = check(r, "boot_done"), pe = check(r, "plugins_enabled"), rc = check(r, "rcon_checks");
313	  const st = (c: CheckResult | null): GateCheck["status"] => (!c ? "not_run" : c.status === "pass" && c.evidence.length ? "pass" : c.status === "fail" ? "fail" : "not_run");
314	  out.push({ id: "boot", status: st(boot), detail: ev(boot) || "no evidence" });
315	  out.push({ id: "plugins_enabled", status: st(pe), detail: ev(pe) || "no evidence" });
316	  // commands: each `cmd-<label>` evidence line says ok / FAILED; none sent = not_run
317	  const lines = rc?.evidence ?? [];
318	  const cmdLines = o.commands.map((c) => lines.find((l) => l.startsWith(`cmd-${c} `)) ?? null);
319	  if (!o.commands.length) out.push(nr("commands_registered", "the build lists no commands"));
320	  else if (cmdLines.some((l) => l === null)) out.push(nr("commands_registered", `${cmdLines.filter((l) => l === null).length} command check(s) did not run`));
321	  else out.push({ id: "commands_registered", status: cmdLines.every((l) => /: ok/.test(l!)) ? "pass" : "fail", detail: cmdLines.map((l) => l!.slice(0, 80)).join(" | ").slice(0, 300) });
322	  if (!o.datapacks) out.push(nr("datapack_loaded", "no data pack in this build"));
323	  else {
324	    const dl = lines.find((l) => l.startsWith("datapacks-enabled "));
325	    out.push(dl ? { id: "datapack_loaded", status: /: ok/.test(dl) ? "pass" : "fail", detail: dl.slice(0, 300) } : nr("datapack_loaded", "the data pack check did not run"));
326	  }
327	  return out;
328	}
329	
330	/** Verdict + label from the runner summary (the summary already refuses success when a required stage was skipped). */
331	export function gateVerdict(s: TestFlightSummary | null, checks: GateCheck[]): { verdict: GateVerdict; label: string | null } {
332	  if (!s) return { verdict: "not_run", label: null };
333	  if (s.overall === "busy" || s.overall === "error") return { verdict: "not_run", label: null };
334	  const anyFail = checks.some((c) => c.status === "fail" && c.id !== "commands_registered") || s.overall === "failed";
335	  if (anyFail) return { verdict: "failed", label: null };
336	  if (!s.success) return { verdict: "incomplete", label: null };
337	  return { verdict: "passed", label: `boot-tested on Paper ${s.version}` };
338	}
339	
340	/** R42: the build's vanilla check summary (ModBuild.result.assets.vanilla), trimmed for the flight record. null = not run. */
341	export function vanillaOf(result: unknown): StoredFlight["vanilla"] {
342	  const v = (result as { assets?: { vanilla?: unknown } } | null)?.assets?.vanilla as NonNullable<StoredFlight["vanilla"]> | undefined;
343	  if (!v || typeof v !== "object" || (v.status !== "checked" && v.status !== "not_run") || !v.counts) return null;
344	  return { status: v.status, version: String(v.version), counts: { error: Number(v.counts.error) || 0, warn: Number(v.counts.warn) || 0, info: Number(v.counts.info) || 0 }, issues: (Array.isArray(v.issues) ? v.issues : []).slice(0, 8) };
345	}
346	/** One note line for a checked summary with problems, or null. */
347	export function vanillaNote(v: StoredFlight["vanilla"]): string | null {
348	  if (!v || v.status !== "checked" || !(v.counts.error + v.counts.warn)) return null;
349	  return `vanilla check (${v.version}): ${v.counts.error} error(s), ${v.counts.warn} warning(s)${v.issues[0] ? `, e.g. ${v.issues[0].path}: ${v.issues[0].message}` : ""}`.slice(0, 300);
350	}
351	
352	export const backoffMs = (busyRetries: number) => Math.min(10 * 60_000, 30_000 * 2 ** Math.max(0, busyRetries));
353	
354	/** Read a stored result back (tolerant). */
355	export function readStoredFlight(raw: unknown): StoredFlight | null {
356	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
357	  const r = raw as StoredFlight;
358	  return r.schema === 1 && typeof r.state === "string" && Array.isArray(r.checks) ? r : null;
359	}
360	
361	/** Is this build due a flight now? (pure scheduling) */
362	export function dueForFlight(stored: StoredFlight | null, now: Date): boolean {
363	  if (!stored) return true;
364	  if (stored.state === "queued") return !stored.nextAt || new Date(stored.nextAt).getTime() <= now.getTime();
365	  if (stored.state === "running") return new Date(stored.at).getTime() < now.getTime() - 30 * 60_000; // a worker died mid-flight
366	  return false;
367	}
368	
369	/** Optional gate on publish / install: only a FAILED flight blocks, and only with the flag on. "Not run" never blocks. */
370	export function flightBlocks(stored: unknown, env: Record<string, string | undefined> = process.env): { blocked: false } | { blocked: true; reason: string } {
371	  const f = readStoredFlight(stored);
372	  // perf safety: a FAILED stress test blocks by default, independent of CYRUS_TESTFLIGHT_BLOCK_ON_FAIL (CYRUS_PERF_BLOCK_ON_FAIL=0 = off)
373	  if (f?.state === "done" && f.stress) { const sb = stressBlocks(f.stress, f.version, env); if (sb.blocked) return sb; }
374	  if (env[BLOCK_FLAG] !== "1") return { blocked: false };
375	  if (f?.state === "done" && f.verdict === "failed") {
376	    const bad = f.checks.filter((c) => c.status === "fail").map((c) => c.id.replace(/_/g, " "));
377	    return { blocked: true, reason: `This version failed its Test Flight on Paper ${f.version} (${bad.join(", ") || "boot"}). Fix it with a change request before installing or publishing it.` };
378	  }
379	  return { blocked: false };
380	}
