404	export const TF_DEFAULT_ROOT = cyrusConfig().testFlightRoot;
405	export const DEFAULT_TIMEOUTS = { bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 } as const;
406	export const DEFAULT_MEMORY = { xmxMb: 1024, rssCapMb: 1800 } as const;
407	const RESERVED_COMMANDS = /^\/?(stop|restart|op|deop|reload)\b/i;
408	const SHA256 = /^[0-9a-f]{64}$/;
409	/** Same rule as lib.js SERVER_FILE_RE: relative, under plugins/, plain segments only. */
410	export const SERVER_FILE_RE = /^plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}){0,3}$/;
411	export const MAX_SERVER_FILES = 16;
412	export const MAX_SERVER_FILE_BYTES = 64 * 1024;
413	/** Same rules as lib.js (runner tf-lite-2). */
414	export const SEED_NAME_RE = /^[a-z0-9][a-z0-9._-]{0,63}$/;
415	export const SEED_TO_RE = /^(libraries|plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/(?!\.\.?(\/|$))[A-Za-z0-9_.-]{1,64}){0,4})$/;
416	export const COLLECT_RE = /^[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/(?!\.\.?(\/|$))[A-Za-z0-9_.-]{1,64}){0,7}\/?$/;
417	export const MAX_SEEDS = 8;
418	export const MAX_COLLECT = 12;
