420	function checkFile(f: ServerFile | undefined, key: string, errs: string[]) {
421	  if (!f || typeof f.path !== "string" || !SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) errs.push(`${key}.path must be a relative path under plugins/ (plain segments)`);
422	  if (!f || typeof f.content !== "string" || Buffer.byteLength(f.content, "utf8") > MAX_SERVER_FILE_BYTES) errs.push(`${key}.content must be text of at most ${MAX_SERVER_FILE_BYTES} bytes`);
423	}
424	
425	function checkMatchers(list: LogMatcher[] | undefined, key: string, errs: string[]) {
426	  for (const [i, m] of (list ?? []).entries()) {
427	    if (!m || typeof m.pattern !== "string" || !m.pattern) { errs.push(`${key}[${i}]: pattern is required`); continue; }
428	    if (m.pattern.length > 400) errs.push(`${key}[${i}]: pattern longer than 400 chars`);
429	    try { new RegExp(m.pattern, (m.flags ?? "").replace(/[^imsu]/g, "")); } catch (e) { errs.push(`${key}[${i}]: ${(e as Error).message}`); }
430	  }
