436	/** Validate a caller spec. `lookup` is injectable for tests; defaults to the real registry. */
437	export function validateSpec(spec: TestFlightSpec, lookup: (id: string) => VersionRow | null = getVersion): SpecCheck {
438	  const errs: string[] = [];
439	  const row = lookup(String(spec?.version ?? ""));
440	  if (!row) errs.push(`Minecraft ${spec?.version} is not in the version registry`);
441	  else {
442	    if (!row.paperBuild || !Number.isInteger(row.paperBuild)) errs.push(`${row.id} has no pinned Paper server build, so it cannot be test-flown`);
443	    if (!SHA256.test(String(row.paperServerSha256 ?? ""))) errs.push(`${row.id} has no pinned Paper server sha256`);
444	  }
445	  const arts = [...(spec.plugins ?? []).map((a, i) => ["plugins", i, a] as const), ...(spec.datapacks ?? []).map((a, i) => ["datapacks", i, a] as const)];
446	  for (const [k, i, a] of arts) {
447	    const hasLocal = typeof a?.localPath === "string" && a.localPath.length > 0;
448	    const hasRemote = typeof a?.remotePath === "string" && a.remotePath.length > 0;
449	    if (hasLocal === hasRemote) errs.push(`${k}[${i}]: give exactly one of localPath or remotePath`);
450	    if (a?.sha256 != null && !SHA256.test(a.sha256)) errs.push(`${k}[${i}]: sha256 must be 64 lowercase hex chars`);
451	    if (k === "plugins" && !/\.jar$/.test(String(a?.localPath ?? a?.remotePath ?? ""))) errs.push(`plugins[${i}]: must be a .jar`);
452	  }
453	  for (const [i, d] of (spec.datapacks ?? []).entries()) if (!/^[a-z0-9_.-]{1,64}$/.test(String(d?.name ?? ""))) errs.push(`datapacks[${i}].name must be 1-64 chars of a-z 0-9 _ . -`);
454	  const pluginNames = new Set<string>();
455	  for (const p of spec.plugins ?? []) {
456	    const b = String(p.localPath ?? p.remotePath ?? "").split("/").pop()!;
457	    if (pluginNames.has(b)) errs.push(`two plugins share the file name ${b}`);
458	    pluginNames.add(b);
459	  }
460	  for (const [i, c] of (spec.rcon ?? []).entries()) {
461	    const cmd = String(c?.command ?? "");
462	    if (!cmd.trim() || cmd.length > 200 || /[\r\n]/.test(cmd)) errs.push(`rcon[${i}].command must be one line of 1-200 chars`);
463	    if (RESERVED_COMMANDS.test(cmd.trim())) errs.push(`rcon[${i}]: '${cmd}' is reserved for the runner`);
464	    if (c.expect != null && !Array.isArray(c.expect)) errs.push(`rcon[${i}].expect must be an array of strings`);
465	    if (c.writeFile != null) checkFile(c.writeFile, `rcon[${i}].writeFile`, errs);
466	    if (c.waitMs != null && !(Number.isInteger(c.waitMs) && c.waitMs >= 0 && c.waitMs <= 30000)) errs.push(`rcon[${i}].waitMs must be 0-30000`);
467	  }
468	  if ((spec.files ?? []).length > MAX_SERVER_FILES) errs.push(`files: at most ${MAX_SERVER_FILES}`);
469	  for (const [i, f] of (spec.files ?? []).entries()) checkFile(f, `files[${i}]`, errs);
470	  if ((spec.seeds ?? []).length > MAX_SEEDS) errs.push(`seeds: at most ${MAX_SEEDS}`);
471	  for (const [i, sd] of (spec.seeds ?? []).entries()) {
472	    if (!SEED_NAME_RE.test(String(sd?.from ?? ""))) errs.push(`seeds[${i}].from must be a seed name under <root>/seeds`);
473	    if (!SEED_TO_RE.test(String(sd?.to ?? "")) || String(sd?.to).split("/").includes("..")) errs.push(`seeds[${i}].to must be libraries or a path under plugins/`);
474	  }
475	  if ((spec.collect ?? []).length > MAX_COLLECT) errs.push(`collect: at most ${MAX_COLLECT}`);
476	  for (const [i, c] of (spec.collect ?? []).entries()) {
477	    if (typeof c !== "string" || !COLLECT_RE.test(c) || c.split("/").includes("..")) errs.push(`collect[${i}] must be a relative path of plain segments`);
478	  }
479	  checkMatchers(spec.logMatchers, "logMatchers", errs);
480	  checkMatchers(spec.logIgnore, "logIgnore", errs);
481	  if (spec.logMatchers && spec.logMatchers.length === 0) errs.push("logMatchers: an empty list would make the log check vacuous; omit it to use the defaults");
482	  const t = spec.timeouts ?? {};
483	  for (const [k, max] of [["bootSec", 600], ["rconSec", 60], ["stopSec", 120], ["totalSec", 900]] as const) {
484	    const v = t[k];
485	    if (v != null && !(Number.isFinite(v) && v > 0 && v <= max)) errs.push(`timeouts.${k} must be 1-${max}`);
486	  }
487	  const m = spec.memory ?? {};
488	  if (m.xmxMb != null && !(Number.isInteger(m.xmxMb) && m.xmxMb >= 256 && m.xmxMb <= 1024)) errs.push("memory.xmxMb must be 256-1024 (node-2 allows at most -Xmx1g)");
489	  if (m.rssCapMb != null && !(Number.isInteger(m.rssCapMb) && m.rssCapMb >= 512 && m.rssCapMb <= 2048)) errs.push("memory.rssCapMb must be 512-2048");
490	  for (const s of spec.requireStages ?? []) if (!(CHECK_IDS as readonly string[]).includes(s)) errs.push(`requireStages: unknown stage ${s}`);
491	  if (spec.world != null && (Object.keys(spec.world).some((k) => k !== "generateStructures") || (spec.world.generateStructures != null && typeof spec.world.generateStructures !== "boolean"))) errs.push("world may only hold generateStructures (boolean)");
492	  if (spec.playtest != null) {
493	    errs.push(...validatePlaytestPlan(spec.playtest));
494	    const pv = playtestVersion(String(spec.version));
495	    if (!pv.ok) errs.push(pv.reason);
496	  }
497	  if (spec.stress != null) errs.push(...validateStress(spec.stress));
498	  if (spec.worldgen != null) errs.push(...validateWorldgen(spec.worldgen));
499	  if (errs.length || !row) return { ok: false, errors: errs };
500	  return { ok: true, row: row as PinnedRow };
501	}
