503	/** Required stages for a spec. The summary uses THIS (what we asked for), not the runner's own flags. */
504	export function requiredStages(spec: TestFlightSpec): Set<CheckId> {
505	  const req = new Set<CheckId>(["boot_done", "startup_log_clean", "clean_stop", "no_leaks"]);
506	  if ((spec.plugins ?? []).length) req.add("plugins_enabled");
507	  if ((spec.rcon ?? []).length || (spec.datapacks ?? []).length) req.add("rcon_checks");
508	  if (spec.playtest) req.add("playtest");
509	  if (spec.stress) req.add("stress");
510	  if (spec.worldgen?.probes?.length) req.add("worldgen");
511	  for (const s of spec.requireStages ?? []) req.add(s);
512	  return req;
513	}
