515	const base = (p: string) => p.split("/").pop()!;
516	
517	/** Resolve a validated spec for the runner. Local artifacts are mapped to `<root>/inbox/<runId>/<file>`. */
518	export function resolveSpec(spec: TestFlightSpec, opts: { runId: string; root?: string; lookup?: (id: string) => VersionRow | null }): ResolvedSpec {
519	  const v = validateSpec(spec, opts.lookup);
520	  if (!v.ok) throw new Error(`invalid Test Flight spec: ${v.errors.join("; ")}`);
521	  if (!/^[a-z0-9][a-z0-9-]{5,63}$/.test(opts.runId)) throw new Error("runId must be 6-64 chars of a-z, 0-9, -");
522	  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
523	  const inbox = `${root}/inbox/${opts.runId}`;
524	  return {
525	    schema: 1,
526	    runId: opts.runId,
527	    version: v.row.id,
528	    javaRelease: v.row.javaRelease,
529	    paper: { build: v.row.paperBuild, sha256: v.row.paperServerSha256 },
530	    plugins: (spec.plugins ?? []).map((p) => ({ path: p.remotePath ?? `${inbox}/${base(p.localPath!)}`, ...(p.sha256 ? { sha256: p.sha256 } : {}) })),
531	    datapacks: (spec.datapacks ?? []).map((d) => ({ name: d.name, path: d.remotePath ?? `${inbox}/dp-${d.name}` })),
532	    ...(spec.resourcePack ? { resourcePack: spec.resourcePack } : {}),
533	    ...(spec.files?.length ? { files: spec.files } : {}),
534	    ...(spec.seeds?.length ? { seeds: spec.seeds } : {}),
535	    ...(spec.collect?.length ? { collect: spec.collect } : {}),
536	    rcon: spec.rcon ?? [],
537	    ...(spec.logMatchers ? { logMatchers: spec.logMatchers } : {}),
538	    ...(spec.logIgnore ? { logIgnore: spec.logIgnore } : {}),
539	    timeouts: { ...DEFAULT_TIMEOUTS, ...(spec.timeouts ?? {}) },
540	    memory: { ...DEFAULT_MEMORY, ...(spec.memory ?? {}) },
541	    keepDir: !!spec.keepDir,
542	    ...(spec.playtest ? { playtest: spec.playtest } : {}),
543	    ...(spec.stress ? { stress: spec.stress } : {}),
544	    ...(spec.worldgen ? { worldgen: spec.worldgen } : {}),
545	    ...(spec.world ? { world: { ...(spec.world.generateStructures != null ? { generateStructures: spec.world.generateStructures } : {}) } } : {}),
546	  };
547	}
