// Cyrus R5 Test Flight gate, worker half (SERVER ONLY). A sweep picks recent succeeded builds without a stored flight
// (or whose busy retry is due), runs ONE flight per tick through the injectable Test Flight invoker (./client.ts,
// ssh to node-2), and stores the result on ModBuild.cyrus.testFlight (atomic jsonb merge). OFF unless
// CYRUS_TESTFLIGHT_GATE=1: off, the sweep returns before any database read.
// Wiring 2: with CYRUS_PLAYTEST=1 as well, the build's stored ModSpec (CyrusRevision.spec of the revision linked to the
// build) becomes a playtest plan flown in the SAME flight; its verdict is stored apart (StoredFlight.playtest) and never
// changes the boot verdict or the install block. No stored spec = "not run", never a pass.
// Never runs inside a request handler. One flight at a time per process (`inFlight`), node-2 also serialises.
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { GATE_FLAG, GATE_VERSION, MAX_BUSY_RETRIES, MAX_FLIGHTS_PER_BUILD, backoffMs, dueForFlight, gateChecks, gateVerdict, planGateFlight, readStoredFlight, vanillaNote, vanillaOf, type GateArtifacts, type GateBuild, type StoredFlight } from "./gate";
import type { RunResult } from "./client";
import type { TestFlightSpec } from "./types";
import { summarize } from "./summary";
import { planFromSpec, playtestEnabled, playtestVerdict, playtestVersion, withPlaytest, type PlaytestPlan, type TestCoverage } from "../playtest";
import type { ModSpec } from "../engine-core/spec";
import { botModeInputsFromCyrus, storedStress, stressBotModeFor, stressEnabled, stressSpecFor } from "./stress";
import { modLoadProfile } from "./stress-profile";
import { storedWorldgen, worldgenProbesEnabled, worldgenProbesFor, type WorldgenProbe } from "./worldgen";

export type GateDeps = {
  env?: Record<string, string | undefined>;
  now?: () => Date;
  /** Recent succeeded builds (newest first) with their stored cyrus meta. */
  candidates(limit: number): Promise<(GateBuild & { cyrus: unknown; finishedAt: Date | null })[]>;
  /** Where the build's jar is on this host, and its data packs / pack config written to `dir` for the flight. */
  artifacts(b: GateBuild, dir: string): Promise<GateArtifacts>;
  run(spec: TestFlightSpec): Promise<RunResult>;
  store(buildId: string, flight: StoredFlight): Promise<void>;
  /** Wiring 2: the build's stored ModSpec (the revision linked to the build), for the playtest bots. Absent/null = none. */
  spec?(b: GateBuild): Promise<{ spec: ModSpec; revisionId: string | null } | null>;
  /** Perf safety: the build's jar bytes (for the stress coverage: which of the mod's events the load fired). Absent = unknown. */
  jar?(b: GateBuild, art: GateArtifacts): Promise<Buffer | null>;
};

type Playtest = { plan: PlaytestPlan; coverage: TestCoverage[]; revisionId: string | null } | { notRun: string; revisionId: string | null } | null;

/** CYRUS_PLAYTEST: a plan from the build's stored ModSpec, flown in the SAME flight as the boot checks. null = off. */
export async function playtestFor(b: GateBuild, deps: GateDeps, env: Record<string, string | undefined>): Promise<Playtest> {
  if (!playtestEnabled(env)) return null;
  const s = deps.spec ? await deps.spec(b).catch(() => null) : null;
  if (!s) return { notRun: "not run: this build has no stored ModSpec", revisionId: null };
  if (s.spec.target.version !== b.mcVersion) return { notRun: `not run: the ModSpec targets ${s.spec.target.version}, the build is for ${b.mcVersion}`, revisionId: s.revisionId };
  const pv = playtestVersion(b.mcVersion);
  if (!pv.ok) return { notRun: pv.reason, revisionId: s.revisionId };
  const gen = planFromSpec(s.spec);
  if (!gen.plan) return { notRun: "not run: no acceptance test could be scripted", revisionId: s.revisionId };
  return { plan: gen.plan, coverage: gen.coverage, revisionId: s.revisionId };
}

let inFlight = false;

export async function testFlightGateSweep(deps: GateDeps, opts: { maxFlights?: number; lookback?: number } = {}): Promise<{ ran: number; queued: number; notRun: number; skipped: string | null }> {
  const env = deps.env ?? process.env;
  if (env[GATE_FLAG] !== "1") return { ran: 0, queued: 0, notRun: 0, skipped: "switched off" };
  if (inFlight) return { ran: 0, queued: 0, notRun: 0, skipped: "a flight is already running in this worker" };
  inFlight = true;
  const now = deps.now ?? (() => new Date());
  let ran = 0, queued = 0, notRun = 0;
  try {
    const rows = await deps.candidates(opts.lookback ?? 50);
    for (const b of rows) {
      if (ran >= (opts.maxFlights ?? 1)) break;
      const prev = readStoredFlight((b.cyrus as { testFlight?: unknown } | null)?.testFlight);
      if (!dueForFlight(prev, now())) continue;
      const r = await flyOne(b, prev, deps, now);
      if (r === "ran") ran++; else if (r === "queued") queued++; else notRun++;
    }
  } finally { inFlight = false; }
  return { ran, queued, notRun, skipped: null };
}

const base = (b: GateBuild, prev: StoredFlight | null, now: Date): StoredFlight => ({ schema: 1, gate: GATE_VERSION, state: "queued", version: b.mcVersion, verdict: "not_run", label: null, checks: [], flights: prev?.flights ?? 0, busyRetries: prev?.busyRetries ?? 0, at: now.toISOString() });

export async function flyOne(b: GateBuild & { /** stored ModBuild.cyrus (planned lanes pick the stress bot) */ cyrus?: unknown }, prev: StoredFlight | null, deps: GateDeps, now: () => Date): Promise<"ran" | "queued" | "not_run"> {
  const cur = base(b, prev, now());
  if (cur.flights >= MAX_FLIGHTS_PER_BUILD) { await deps.store(b.id, { ...prev!, state: "gave_up", reason: `not run: the per-build limit of ${MAX_FLIGHTS_PER_BUILD} flights was reached`, at: now().toISOString() }); return "not_run"; }
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-tfgate-"));
  try {
    let art: GateArtifacts;
    try { art = await deps.artifacts(b, dir); }
    catch (e) { const reason = `not run: ${(e as Error).message}`.slice(0, 300); await deps.store(b.id, { ...cur, state: "not_run", reason, checks: gateChecks(b, null, null, { commands: [], datapacks: 0, reason }) }); return "not_run"; }
    const plan = planGateFlight(b, art);
    if (!plan.ok) { await deps.store(b.id, { ...cur, state: "not_run", reason: plan.reason, checks: gateChecks(b, null, null, { commands: [], datapacks: art.datapacks.length, reason: plan.reason }) }); return "not_run"; }
    const env = deps.env ?? process.env;
    const pt = await playtestFor(b, deps, env);
    const withPt = pt && "plan" in pt ? withPlaytest(plan.spec, pt.plan) : plan.spec;
    // perf safety: the stress phase rides in the same flight (after the boot checks and the playtest)
    // survival combat bot for mob / boss mods (creative players are ignored by mob AI), from the build's planned lanes
    const botMode = stressBotModeFor(botModeInputsFromCyrus(b.cyrus));
    const stress = stressEnabled(env) ? stressSpecFor({ version: b.mcVersion, commands: plan.commands, botMode: botMode.mode, env }) : null;
    // worldgen density probes (CYRUS_TESTFLIGHT_WORLDGEN=1): from the data pack specs the packs were rebuilt from
    const probes: WorldgenProbe[] = worldgenProbesEnabled(env) ? art.datapacks.flatMap((d) => (d.spec && d.namespace ? worldgenProbesFor(d.spec, d.namespace).probes : [])).filter((p, i, a) => a.findIndex((x) => x.id === p.id) === i).slice(0, 8) : [];
    const withWg = probes.length ? { ...withPt, worldgen: { probes } } : withPt;
    const withSt = stress ? { ...withWg, stress } : withWg;
    // the stress phase and the worldgen probes (chunk generation) need more wall time than a boot
    const flown = stress || probes.length ? { ...withSt, timeouts: { ...(withSt.timeouts ?? {}), totalSec: Math.max(withSt.timeouts?.totalSec ?? 420, 600) } } : withSt;
    await deps.store(b.id, { ...cur, state: "running" });
    let res: RunResult;
    try { res = await deps.run(flown); }
    catch (e) {
      const flights = cur.flights + 1;
      const giveUp = flights >= MAX_FLIGHTS_PER_BUILD;
      await deps.store(b.id, { ...cur, flights, state: giveUp ? "gave_up" : "queued", lastError: (e as Error).message.slice(0, 300), nextAt: new Date(now().getTime() + backoffMs(cur.busyRetries)).toISOString(), reason: giveUp ? "not run: the test server could not be reached" : undefined, checks: gateChecks(b, null, null, { commands: plan.commands, datapacks: art.datapacks.length, reason: "not run: the test server could not be reached" }) });
      return giveUp ? "not_run" : "queued";
    }
    if (res.report.status === "busy") {
      const busyRetries = cur.busyRetries + 1;
      const giveUp = busyRetries > MAX_BUSY_RETRIES;
      await deps.store(b.id, { ...cur, busyRetries, state: giveUp ? "gave_up" : "queued", nextAt: new Date(now().getTime() + backoffMs(busyRetries)).toISOString(), reason: giveUp ? "not run: the test server stayed busy" : undefined, checks: gateChecks(b, res.report, null, { commands: plan.commands, datapacks: art.datapacks.length }) });
      return giveUp ? "not_run" : "queued";
    }
    // the boot verdict is judged on the boot spec alone: a playtest flown alongside never changes it
    const bootSummary = flown === plan.spec ? res.summary : summarize(plan.spec, res.report);
    const checks = gateChecks(b, res.report, bootSummary, { commands: plan.commands, datapacks: art.datapacks.length });
    const v = gateVerdict(bootSummary, checks);
    let playtest: StoredFlight["playtest"] = undefined;
    if (pt && "plan" in pt) {
      const pv = playtestVerdict(pt.plan, res.report, pt.coverage);
      playtest = { verdict: pv.verdict, label: pv.label.slice(0, 300), counts: pv.counts, scenarios: pv.scenarios.slice(0, 16).map((x) => ({ id: x.id, status: x.status, reason: x.reason ? x.reason.slice(0, 240) : null })), specRevisionId: pt.revisionId };
    } else if (pt) playtest = { verdict: "not_run", label: pt.notRun, specRevisionId: pt.revisionId };
    let stressRec: StoredFlight["stress"] = undefined;
    if (stress) {
      const jar = deps.jar ? await deps.jar(b, art).catch(() => null) : null;
      const prof = jar ? modLoadProfile(jar) : null;
      stressRec = { ...storedStress(res.report.stress, { events: prof?.events ?? null, repeatingTasks: prof?.repeatingTasks ?? null }), botMode: { mode: botMode.mode, why: botMode.why } };
    }
    const eng = res.report.engine;
    await deps.store(b.id, {
