/** Default wiring for the Nxeon worker (lazy imports keep this module free of Nxeon internals at load time). */
export async function defaultGateDeps(env: Record<string, string | undefined> = process.env): Promise<GateDeps> {
  const { cyrusDb: db } = await import("../db");
  const { jarPathFor } = await import("../builder/paths");
  const { getHost } = await import("../host");
  const host = getHost();
  const mergeCyrusKey = host.builds.mergeCyrusKey;
  const { runTestFlight } = await import("./client");
  const { readBuildAssets } = await import("../assets/sync");
  const { rebuildForDelivery } = await import("../datapack/deliver");
  const { loadCatalog, pinFor } = await import("../managed/catalog");
  const { readManagedArtifact } = await import("../managed/installer");
  const { applyPackChange, serializeLoaderConfig } = await import("../packhost/loader-config");
  const { createHash } = await import("node:crypto");
  const onBuildSettled = host.mods.onBuildSettled;
  return {
    env,
    async candidates(limit) {
      const since = new Date(Date.now() - 7 * 24 * 3600_000);
      const rows = await db.modBuild.findMany({ where: { status: "succeeded", finishedAt: { gte: since }, jarPath: { not: null } }, orderBy: { finishedAt: "desc" }, take: limit, select: { id: true, mcVersion: true, pluginName: true, jarSha256: true, result: true, cyrus: true, finishedAt: true } });
      return rows;
    },
    async artifacts(b, dir) {
      const a = readBuildAssets(b.result);
      const datapacks: GateArtifacts["datapacks"] = [];
      if (a?.datapacks?.length && a.revisionId) {
        const rows = await db.cyrusProjectAsset.findMany({ where: { revisionId: a.revisionId, kind: "datapack" }, select: { assetKey: true, provenance: true } });
        for (const row of rows) {
          const rb = rebuildForDelivery((row.provenance ?? {}) as Record<string, unknown>, a.namespace);
          if (!rb.ok) continue;
          const name = `nxeon-${a.namespace}-${rb.name}`.toLowerCase().replace(/[^a-z0-9_.-]/g, "-").slice(0, 64);
          const p = path.join(dir, `${name}.zip`); writeFileSync(p, rb.zip);
          datapacks.push({ name, localPath: p, spec: (row.provenance as { spec?: unknown } | null)?.spec, namespace: a.namespace });
        }
      }
      let packLoader: GateArtifacts["packLoader"] = null;
      if (a?.status === "ready" && a.loader) {
        try {
          const pin = pinFor(loadCatalog(), "nxeon-pack-loader", b.mcVersion);
          if (pin.ok) {
            const bytes = await readManagedArtifact(pin.entry);
            const jp = path.join(dir, "NxeonPackLoader.jar"); writeFileSync(jp, bytes);
            const ch = applyPackChange(null, { op: "upsert", namespace: a.namespace, role: "main", sha1: a.loader.sha1, prompt: a.loader.prompt, required: a.loader.required }, { urlFor: () => a.loader!.url });
            if (ch.ok) packLoader = { localPath: jp, sha256: createHash("sha256").update(bytes).digest("hex"), config: serializeLoaderConfig(ch.config) };
          }
        } catch { packLoader = null; }
      }
      return { jarPath: jarPathFor(b.id), datapacks, packLoader };
    },
    run: (spec) => runTestFlight(spec),
    async jar(_b, art) { const { readFileSync } = await import("node:fs"); try { return readFileSync(art.jarPath); } catch { return null; } },
    async spec(b) {
      const { validateModSpec } = await import("../engine-core/spec");
      const rows = await db.cyrusRevision.findMany({ where: { modBuildId: b.id }, orderBy: { seq: "desc" }, take: 5, select: { id: true, spec: true } });
      for (const r of rows) {
        if (r.spec == null) continue;
        const v = validateModSpec(r.spec);
        if (v.ok) return { spec: v.spec, revisionId: r.id };
      }
      return null;
    },
    async store(id, flight) {
      await mergeCyrusKey(id, "testFlight", flight);
      // the NxLabs page shows the boot test: regenerate it once the result is final (never fails the flight)
      if (flight.state !== "queued" && flight.state !== "running") {
        const row = await db.modBuild.findUnique({ where: { id } }).catch(() => null);
        if (row) await onBuildSettled(row).catch(() => {});
      }
    },
  };
}
// Thin Test Flight invoker: push the runner + artifacts to node-2, run ONE flight, parse the report, summarise.
// Not wired into the live build path. All I/O goes through the injectable `Remote`, so tests use a fake.
// Server-only (node:child_process / node:fs).
import { spawn } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import type { TestFlightReport, TestFlightSpec, TestFlightSummary, ResolvedSpec } from "./types";
import { resolveSpec, validateSpec, TF_DEFAULT_ROOT } from "./spec";
import { summarize } from "./summary";
import { cyrusConfig } from "../config";

export type ExecResult = { code: number | null; stdout: string; stderr: string };
/** Runs a shell command line on the build host. `input` is piped to stdin. */
export type Remote = { exec: (command: string, opts?: { input?: Buffer; timeoutMs?: number }) => Promise<ExecResult> };

export const NODE2 = cyrusConfig().buildHost;
export const BUSY_EXIT = 75;

/** POSIX single-quote a word for a remote shell. */
export const shq = (s: string) => `'${String(s).replace(/'/g, `'\\''`)}'`;

/** Real transport: ssh with BatchMode (no prompts), hard local timeout (SIGKILL of the ssh child we spawned). */
export function sshRemote(host = NODE2): Remote {
  return {
    exec: (command, opts = {}) => new Promise((resolve) => {
      const child = spawn("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", host, command], { stdio: ["pipe", "pipe", "pipe"] });
      let stdout = "", stderr = "";
      child.stdout.on("data", (d) => (stdout += d));
      child.stderr.on("data", (d) => (stderr += d));
      const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
      child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
      child.stdin.on("error", () => {});
      child.stdin.end(opts.input ?? undefined);
    }),
  };
}

export type RunOptions = {
  remote?: Remote;
  root?: string;
  /** Directory holding runner.js + lib.js (default: the repo copy). */
  runnerDir?: string;
  runId?: string;
  readFile?: (p: string) => Buffer;
  /** Files of a local datapack directory, relative path -> absolute path. */
  listDir?: (dir: string) => { rel: string; abs: string }[];
};

export type RunResult = { report: TestFlightReport; summary: TestFlightSummary; resolved: ResolvedSpec; stderr: string };

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

function walk(dir: string, rel = ""): { rel: string; abs: string }[] {
  const out: { rel: string; abs: string }[] = [];
  for (const e of readdirSync(path.join(dir, rel)).sort()) {
    const r = rel ? `${rel}/${e}` : e;
    if (statSync(path.join(dir, r)).isDirectory()) out.push(...walk(dir, r));
    else out.push({ rel: r, abs: path.join(dir, r) });
  }
  return out;
}

export function newRunId(version: string): string {
  return `tf-${version.replace(/[^0-9]+/g, "-")}-${Date.now().toString(36)}-${randomBytes(3).toString("hex")}`.toLowerCase();
}

/** Minimal POSIX ustar archive (regular files only) so one ssh call can carry every artifact. */
export function tarball(entries: { name: string; data: Buffer }[]): Buffer {
  const blocks: Buffer[] = [];
  for (const e of entries) {
    if (!e.name || e.name.startsWith("/") || e.name.split("/").includes("..") || Buffer.byteLength(e.name) > 99) throw new Error(`bad tar entry name ${e.name}`);
    const h = Buffer.alloc(512);
    h.write(e.name, 0, "utf8");
    h.write("0000644\0", 100); h.write("0000000\0", 108); h.write("0000000\0", 116);
    h.write(e.data.length.toString(8).padStart(11, "0") + "\0", 124);
    h.write("00000000000\0", 136);
    h.fill(" ", 148, 156);
    h.write("0", 156);
    h.write("ustar\0" + "00", 257);
    let sum = 0;
    for (const b of h) sum += b;
    h.write(sum.toString(8).padStart(6, "0") + "\0 ", 148);
    blocks.push(h, e.data, Buffer.alloc((512 - (e.data.length % 512)) % 512));
  }
  blocks.push(Buffer.alloc(1024));
  return Buffer.concat(blocks);
}

/**
 * Files the runner needs on node-2: [repo path under the runner dir, flat name under <root>/runner/].
 * playtest-lib.js + bot.js + the pinned bot package files ride along (runner tf-lite-4).
 */
export const RUNNER_FILES: readonly (readonly [string, string])[] = [
  ["lib.js", "lib.js"], ["runner.js", "runner.js"], ["playtest-lib.js", "playtest-lib.js"], ["bot.js", "bot.js"],
  ["bot/package.json", "bot-package.json"], ["bot/package-lock.json", "bot-package-lock.json"],
  ["stress-lib.js", "stress-lib.js"], ["stress-bot.js", "stress-bot.js"],
];

/** Push the runner if node-2's copy differs (content hash), so every flight runs the code in this repo. */
async function ensureRunner(remote: Remote, root: string, dir: string, read: (p: string) => Buffer) {
  const files = RUNNER_FILES.map(([, f]) => f);
  const data = new Map(RUNNER_FILES.map(([src, f]) => [f, read(path.join(dir, src))] as const));
  const want = files.map((f) => `${sha256(data.get(f)!)}  ${root}/runner/${f}`).join("\n") + "\n";
  const have = await remote.exec(`sha256sum ${files.map((f) => shq(`${root}/runner/${f}`)).join(" ")} 2>/dev/null || true`);
  if (have.stdout === want) return;
  const stage = `${root}/runner/.new-${randomBytes(4).toString("hex")}`;
  const tar = tarball(files.map((f) => ({ name: f, data: data.get(f)! })));
  const r = await remote.exec(`mkdir -p ${shq(stage)} && tar --no-same-owner -xf - -C ${shq(stage)} && ${files.map((f) => `mv -f ${shq(`${stage}/${f}`)} ${shq(`${root}/runner/${f}`)}`).join(" && ")} && rmdir ${shq(stage)}`, { input: tar });
  if (r.code !== 0) throw new Error(`could not install the runner on the build host: ${r.stderr.slice(0, 300)}`);
}

/** Run one Test Flight. Throws only for an invalid spec or a transport failure; every server outcome is in the report. */
export async function runTestFlight(spec: TestFlightSpec, opts: RunOptions = {}): Promise<RunResult> {
  const v = validateSpec(spec);
  if (!v.ok) throw new Error(`invalid Test Flight spec: ${v.errors.join("; ")}`);
  const remote = opts.remote ?? sshRemote();
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const read = opts.readFile ?? ((p: string) => readFileSync(p));
  const list = opts.listDir ?? ((d: string) => walk(d));
  const runId = opts.runId ?? newRunId(spec.version);
  const resolved = resolveSpec(spec, { runId, root });
  const inbox = `${root}/inbox/${runId}`;
  const rel = (p: string) => p.slice(inbox.length + 1);

  // Everything local goes into one tar: plugins, datapacks, the resolved spec.
  const entries: { name: string; data: Buffer }[] = [];
  for (const [i, p] of (spec.plugins ?? []).entries()) {
    if (!p.localPath) continue;
    const buf = read(p.localPath);
    if (p.sha256 && sha256(buf) !== p.sha256) throw new Error(`${p.localPath}: sha256 does not match the spec`);
    resolved.plugins[i].sha256 = sha256(buf); // the runner re-hashes on node-2 and refuses a mismatch
    entries.push({ name: rel(resolved.plugins[i].path), data: buf });
  }
  for (const [i, d] of (spec.datapacks ?? []).entries()) {
    if (!d.localPath) continue;
    if (/\.zip$/.test(d.localPath)) {
      resolved.datapacks[i].path += ".zip";
      entries.push({ name: rel(resolved.datapacks[i].path), data: read(d.localPath) });
      continue;
    }
    for (const f of list(d.localPath)) entries.push({ name: `${rel(resolved.datapacks[i].path)}/${f.rel}`, data: read(f.abs) });
  }
  entries.push({ name: "spec.json", data: Buffer.from(JSON.stringify(resolved)) });

  await ensureRunner(remote, root, opts.runnerDir ?? path.join(process.cwd(), "services/modbuilder/tools/testflight"), read);
  // One call: unpack, run (outer hard timeout on node-2 on top of the runner's own), always remove the inbox.
  const hard = resolved.timeouts.totalSec + 420;
  const cmd = [
    `mkdir -p ${shq(inbox)} && tar --no-same-owner -xf - -C ${shq(inbox)} || exit 3`,
    `TF_ROOT=${shq(root)} timeout -s KILL ${hard} node ${shq(`${root}/runner/runner.js`)} run ${shq(`${inbox}/spec.json`)}`,
    `rc=$?; rm -rf -- ${shq(inbox)}; exit $rc`,
  ].join("\n");
  const r = await remote.exec(cmd, { input: tarball(entries), timeoutMs: (hard + 60) * 1000 });
  const line = r.stdout.trim().split("\n").filter(Boolean).pop() ?? "";
  let report: TestFlightReport;
  try { report = JSON.parse(line); } catch { throw new Error(`runner gave no report (exit ${r.code}): ${(r.stderr || r.stdout).slice(-400)}`); }
  if ((report as unknown as { error?: string }).error) throw new Error(`runner refused the spec: ${JSON.stringify(report).slice(0, 400)}`);
  if (r.code === BUSY_EXIT && report.status !== "busy") report.status = "busy";
  return { report, summary: summarize(spec, report), resolved, stderr: r.stderr };
}

/**
 * Fetch the files a flight collected (spec `collect`, runner tf-lite-2) and remove them from the build host.
 * Each file is re-hashed against the sha256 the runner reported; a mismatch throws.
 */
export async function pullCollected(report: TestFlightReport, opts: { remote?: Remote; root?: string } = {}): Promise<Map<string, Buffer>> {
  const remote = opts.remote ?? sshRemote();
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const out = new Map<string, Buffer>();
  const items = (report.collected ?? []).filter((c) => c.kind === "file" && c.dest && c.sha256);
  const dir = `${root}/collect/${report.runId}`;
  try {
    for (const c of items) {
      if (!c.dest!.startsWith(dir + "/") || c.dest!.split("/").includes("..")) throw new Error(`collected path outside ${dir}: ${c.dest}`);
      const r = await remote.exec(`base64 -w0 ${shq(c.dest!)}`, { timeoutMs: 120000 });
      if (r.code !== 0) throw new Error(`could not read ${c.dest}: ${r.stderr.slice(0, 200)}`);
      const buf = Buffer.from(r.stdout.trim(), "base64");
      if (sha256(buf) !== c.sha256) throw new Error(`${c.path}: sha256 changed in transit`);
      out.set(c.path, buf);
    }
  } finally {
    if (report.runId && /^[a-z0-9][a-z0-9-]{5,63}$/.test(report.runId)) await remote.exec(`rm -rf -- ${shq(dir)}`);
  }
  return out;
}
// Pure Test Flight verdicts. Rules (never relaxed):
// - a check counts as passed only if its status is "pass" AND it carries evidence (a pass with no evidence = not run);
// - required stages come from the spec we sent (requiredStages), not from the runner's own flags;
// - any required stage failed -> "failed"; any required stage missing / not_run -> "incomplete"; neither is success;
// - a busy or errored runner is never success, whatever its checks say.
import type { CheckId, CheckResult, MatrixSummary, Overall, TestFlightReport, TestFlightSpec, TestFlightSummary } from "./types";
import { CHECK_IDS } from "./types";
import { requiredStages } from "./spec";

const STATUSES = new Set(["pass", "fail", "not_run"]);

/** Normalise one check: unknown status or a pass without evidence becomes not_run. */
function effective(c: CheckResult | undefined): "pass" | "fail" | "not_run" {
  if (!c || !STATUSES.has(c.status)) return "not_run";
  if (c.status === "pass" && !(Array.isArray(c.evidence) && c.evidence.some((e) => String(e).trim()))) return "not_run";
  return c.status;
}

export function summarize(spec: TestFlightSpec, report: TestFlightReport): TestFlightSummary {
  const req = requiredStages(spec);
  const byId = new Map<CheckId, CheckResult>();
  for (const c of report.checks ?? []) if ((CHECK_IDS as readonly string[]).includes(c.id) && !byId.has(c.id)) byId.set(c.id, c);
  const passed: CheckId[] = [], failed: CheckId[] = [], skippedRequired: CheckId[] = [], notRunOptional: CheckId[] = [];
  const reasons: string[] = [];
  for (const id of CHECK_IDS) {
    const c = byId.get(id);
    const st = effective(c);
    if (st === "pass") passed.push(id);
    else if (st === "fail") { failed.push(id); if (req.has(id)) reasons.push(`${id} failed${c?.evidence?.[0] ? `: ${c.evidence[0]}` : ""}`); }
    else if (req.has(id)) {
      skippedRequired.push(id);
      reasons.push(!c ? `${id} missing from the report` : c.status === "pass" ? `${id} claimed pass without evidence` : `${id} did not run`);
    } else notRunOptional.push(id);
  }
  if (report.version && spec.version && report.version !== spec.version) reasons.push(`report is for ${report.version}, spec asked for ${spec.version}`);
  let overall: Overall;
  if (report.status === "busy") { overall = "busy"; reasons.unshift("another Test Flight was running; nothing ran"); }
  else if (report.status !== "completed") { overall = "error"; reasons.unshift(`runner did not complete: ${report.notes?.slice(-1)[0] ?? "no detail"}`); }
  else if (report.version !== spec.version) overall = "error";
  else if (failed.some((id) => req.has(id))) overall = "failed";
  else if (skippedRequired.length) overall = "incomplete";
  else overall = "passed";
  return {
    version: spec.version, overall, success: overall === "passed", passed, failed, skippedRequired, notRunOptional, reasons,
    bootMs: report.bootMs ?? null, peakRssKb: report.peakRssKb ?? null, runId: report.runId ?? null,
  };
}

/** One verdict over several versions: success only if every version passed. Worst status wins. */
export function mergeSummaries(list: TestFlightSummary[]): MatrixSummary {
  const rank: Overall[] = ["error", "failed", "busy", "incomplete", "passed"];
  const overall = list.length ? rank.find((r) => list.some((s) => s.overall === r))! : "incomplete";
  return { overall, success: overall === "passed", versions: list };
}

/** Short human line per version, e.g. for a build log or a badge tooltip. Never says "passed" unless it did. */
export function describe(s: TestFlightSummary): string {
  const t = s.bootMs != null ? `, boot ${(s.bootMs / 1000).toFixed(1)}s` : "";
  const r = s.peakRssKb != null ? `, peak RSS ${Math.round(s.peakRssKb / 1024)} MB` : "";
  if (s.success) return `Test Flight passed on Paper ${s.version} (${s.passed.length} checks${t}${r})`;
  return `Test Flight ${s.overall} on Paper ${s.version}: ${s.reasons.slice(0, 3).join("; ") || "no detail"}`;
}

