// Cyrus playtest bots (R3): the typed PLAYTEST PLAN a Test Flight runs with a scripted Mineflayer player.
// Pure + client-safe. Same rules as services/modbuilder/tools/testflight/playtest-lib.js `validatePlaytest` (the
// runner re-validates on node-2; test/cyrus-playtest.test.ts keeps the two in step on shared fixtures).
//
// A plan is a list of SCENARIOS, one per acceptance test of the ModSpec (T-1, T-2, ...), each a list of typed STEPS.
// No free-form code exists: the bot can only do the actions below and check the outcomes below.

export const PLAYTEST_SCHEMA = 1 as const;

/** Actions (the bot does something) and expectations (the bot checks something). */
export const ACTION_STEP_KINDS = ["join", "command", "chat", "server", "wait", "hold", "use_item", "dig", "sneak", "use_on_entity"] as const;
export const EXPECT_STEP_KINDS = ["expect_chat", "expect_no_chat", "expect_inventory", "expect_no_item", "expect_effect", "expect_title", "expect_moved", "expect_entity", "expect_border", "expect_time"] as const;
export const STEP_KINDS = [...ACTION_STEP_KINDS, ...EXPECT_STEP_KINDS] as const;
export type StepKind = (typeof STEP_KINDS)[number];

export type PlaytestStep =
  | { kind: "join"; note?: string }
  /** The bot player runs a command (text starts with "/"). Permission = the player's (op only when plan.op). */
  | { kind: "command"; text: string; note?: string }
  | { kind: "chat"; text: string; note?: string }
  /** A console command over RCON (`{bot}` = the bot's name). `expect` checks the console reply. */
  | { kind: "server"; command: string; expect?: string[]; note?: string }
  | { kind: "wait"; ms: number; note?: string }
  | { kind: "hold"; item: string; note?: string }
  | { kind: "use_item"; note?: string }
  /** Break the block at x y z as the player (survival dig with the held tool; the bot must stand within reach). */
  | { kind: "dig"; x: number; y: number; z: number; note?: string }
  | { kind: "sneak"; on: boolean; note?: string }
  /** Right-click the nearest entity of this type within 6 blocks with the held item. */
  | { kind: "use_on_entity"; type: string; note?: string }
  | { kind: "expect_chat"; contains: string[]; withinMs?: number; note?: string }
  | { kind: "expect_no_chat"; contains: string[]; forMs?: number; note?: string }
  /** At least `count` (default 1) of `item`; `name` = substring of the visible custom name. */
  | { kind: "expect_inventory"; item: string; count?: number; name?: string; withinMs?: number; note?: string }
  | { kind: "expect_no_item"; item: string; forMs?: number; note?: string }
  | { kind: "expect_effect"; effect: string; withinMs?: number; note?: string }
  | { kind: "expect_title"; contains: string[]; withinMs?: number; note?: string }
  /** The bot was moved at least `minBlocks` (default 1) from where it stood when the last action was sent. */
  | { kind: "expect_moved"; minBlocks?: number; withinMs?: number; note?: string }
  /** What THIS client is shown (per-viewer effects): an entity of `type` within 16 blocks (none: true = no such entity), */
  | { kind: "expect_entity"; type: string; none?: boolean; withinMs?: number; note?: string }
  /** the world-border diameter it was last sent, */
  | { kind: "expect_border"; minSize?: number; maxSize?: number; withinMs?: number; note?: string }
  /** and its time of day (0-23999). */
  | { kind: "expect_time"; from: number; to: number; withinMs?: number; note?: string };

export type PlaytestScenario = {
  /** The ModSpec test id this scenario checks. */
  id: string;
  title?: string;
  /** Requirement ids the test covers (copied from the ModSpec). */
  covers?: string[];
  /** Default true: before the scenario the console runs `clear <bot>` and `effect clear <bot>`. */
  reset?: boolean;
  steps: PlaytestStep[];
};

export type PlaytestPlan = {
  schema: 1;
  username?: string;
  /** Make the bot a level-4 operator (ops.json before boot). Needed when tested commands require a permission. */
  op?: boolean;
  /** Time budget for all scenarios (default 90 s) and for the join (default 30 s). */
  totalSec?: number;
  joinSec?: number;
  scenarios: PlaytestScenario[];
};

export const PLAYTEST_LIMITS = { scenarios: 16, steps: 24, text: 200, contains: 6, withinMsMax: 15000, waitMsMax: 10000, totalSecMax: 180, joinSecMax: 60 } as const;
export const PLAYTEST_DEFAULTS = { username: "NxPlaytest", withinMs: 3000, forMs: 1500, totalSec: 90, joinSec: 30 } as const;

/**
 * Minecraft versions the pinned bot (mineflayer 4.39.0, services/modbuilder/tools/testflight/bot/package-lock.json)
 * was RUN against on node-2. Same list as playtest-lib.js BOT_VERSIONS; a version joins it only after a real flight.
 */
export const PLAYTEST_BOT_VERSIONS: readonly string[] = ["1.21.11"];

export const RESERVED_COMMAND_RE = /^\/?(stop|restart|reload|op|deop|kick|ban|ban-ip|pardon|pardon-ip|whitelist|save-off|save-all|minecraft:(stop|reload|op|deop|kick|ban))\b/i;
const USERNAME_RE = /^[A-Za-z0-9_]{3,16}$/;
const ID_RE = /^[a-z0-9_:./-]{1,64}$/;
const SCENARIO_ID_RE = /^T-[1-9][0-9]{0,3}$/;
const REQ_RE = /^REQ-[1-9][0-9]{0,3}$/;

const isStr = (s: unknown, max: number = PLAYTEST_LIMITS.text): s is string =>
  typeof s === "string" && s.trim().length > 0 && s.length <= max && !/[\r\n\u0000]/.test(s);
const intIn = (v: unknown, lo: number, hi: number) => Number.isInteger(v) && (v as number) >= lo && (v as number) <= hi;

const FIELDS: Record<StepKind, string[]> = {
  join: [], command: ["text"], chat: ["text"], server: ["command", "expect"], wait: ["ms"], hold: ["item"], use_item: [],
  dig: ["x", "y", "z"], sneak: ["on"], use_on_entity: ["type"],
  expect_chat: ["contains", "withinMs"], expect_no_chat: ["contains", "forMs"], expect_inventory: ["item", "count", "name", "withinMs"],
  expect_no_item: ["item", "forMs"], expect_effect: ["effect", "withinMs"], expect_title: ["contains", "withinMs"], expect_moved: ["minBlocks", "withinMs"],
  expect_entity: ["type", "none", "withinMs"], expect_border: ["minSize", "maxSize", "withinMs"], expect_time: ["from", "to", "withinMs"],
};

export function stepErrors(raw: unknown, key: string): string[] {
  const st = raw as Record<string, unknown> | null;
  if (!st || typeof st !== "object" || !(STEP_KINDS as readonly string[]).includes(String(st.kind))) return [`${key}.kind must be one of ${STEP_KINDS.join(", ")}`];
  const e: string[] = [];
  const kind = st.kind as StepKind;
  const strList = (v: unknown, k: string) => {
    if (!Array.isArray(v) || !v.length || v.length > PLAYTEST_LIMITS.contains || !v.every((s) => isStr(s))) e.push(`${key}.${k} must be 1-${PLAYTEST_LIMITS.contains} strings of 1-${PLAYTEST_LIMITS.text} chars`);
  };
  const within = (k: string) => { if (st[k] != null && !intIn(st[k], 100, PLAYTEST_LIMITS.withinMsMax)) e.push(`${key}.${k} must be 100-${PLAYTEST_LIMITS.withinMsMax} ms`); };
  const itemId = (k: string, what: string) => { if (!isStr(st[k], 64) || !ID_RE.test(String(st[k]))) e.push(`${key}.${k} must be ${what}`); };
  switch (kind) {
    case "command":
      if (!isStr(st.text) || !st.text.startsWith("/")) e.push(`${key}.text must be one line starting with /`);
      else if (RESERVED_COMMAND_RE.test(st.text.trim())) e.push(`${key}: '${st.text}' is reserved (never sent by a playtest)`);
      break;
    case "chat":
      if (!isStr(st.text) || st.text.startsWith("/")) e.push(`${key}.text must be one line of chat (commands use kind "command")`);
      break;
    case "server":
      if (!isStr(st.command)) e.push(`${key}.command must be one line of 1-${PLAYTEST_LIMITS.text} chars`);
      else if (RESERVED_COMMAND_RE.test(st.command.trim())) e.push(`${key}: '${st.command}' is reserved (never sent by a playtest)`);
      if (st.expect != null) strList(st.expect, "expect");
      break;
    case "wait":
      if (!intIn(st.ms, 1, PLAYTEST_LIMITS.waitMsMax)) e.push(`${key}.ms must be 1-${PLAYTEST_LIMITS.waitMsMax}`);
      break;
    case "hold": itemId("item", "an item id (e.g. diamond or minecraft:diamond)"); break;
    case "dig":
      for (const k of ["x", "y", "z"]) if (!Number.isInteger(st[k]) || Math.abs(st[k] as number) > 30000000) e.push(`${key}.${k} must be an integer block coordinate`);
      if (Number.isInteger(st.y) && ((st.y as number) < -64 || (st.y as number) > 319)) e.push(`${key}.y must be -64..319`);
      break;
    case "sneak": if (typeof st.on !== "boolean") e.push(`${key}.on must be a boolean`); break;
    case "use_on_entity": if (!ID_RE.test(String(st.type ?? ""))) e.push(`${key}.type must be an entity id like pig or minecraft:villager`); break;
    case "expect_chat": strList(st.contains, "contains"); within("withinMs"); break;
    case "expect_no_chat": strList(st.contains, "contains"); within("forMs"); break;
    case "expect_inventory":
      itemId("item", "an item id");
      if (st.count != null && !intIn(st.count, 1, 6400)) e.push(`${key}.count must be 1-6400`);
      if (st.name != null && !isStr(st.name, 100)) e.push(`${key}.name must be 1-100 chars`);
      within("withinMs");
      break;
    case "expect_no_item": itemId("item", "an item id"); within("forMs"); break;
    case "expect_effect": itemId("effect", "an effect id (e.g. speed)"); within("withinMs"); break;
    case "expect_title": strList(st.contains, "contains"); within("withinMs"); break;
    case "expect_entity":
      if (!ID_RE.test(String(st.type ?? ""))) e.push(`${key}.type must be an entity id like pig`);
      if (st.none != null && typeof st.none !== "boolean") e.push(`${key}.none must be a boolean`);
      within("withinMs");
      break;
    case "expect_border":
      if (st.minSize == null && st.maxSize == null) e.push(`${key} needs minSize or maxSize`);
      for (const k of ["minSize", "maxSize"]) if (st[k] != null && !(typeof st[k] === "number" && (st[k] as number) >= 0 && (st[k] as number) <= 60000000)) e.push(`${key}.${k} must be 0-60000000`);
      within("withinMs");
      break;
    case "expect_time":
      if (!intIn(st.from, 0, 23999) || !intIn(st.to, 0, 23999) || (st.from as number) > (st.to as number)) e.push(`${key}: from / to must be 0-23999 ticks with from <= to`);
      within("withinMs");
      break;
    case "expect_moved":
      if (st.minBlocks != null && !(typeof st.minBlocks === "number" && st.minBlocks > 0 && st.minBlocks <= 256)) e.push(`${key}.minBlocks must be >0 and <=256`);
      within("withinMs");
      break;
    default: break;
  }
  for (const k of Object.keys(st)) if (k !== "kind" && k !== "note" && !FIELDS[kind].includes(k)) e.push(`${key}: unknown field ${k} for ${kind}`);
  if (st.note != null && !isStr(st.note, 300)) e.push(`${key}.note must be 1-300 chars`);
  return e;
}

/** Untrusted JSON -> list of problems (empty = a valid plan). Never throws. */
export function validatePlaytestPlan(raw: unknown): string[] {
  const pt = raw as Record<string, unknown> | null;
  if (!pt || typeof pt !== "object" || Array.isArray(pt)) return ["playtest must be an object"];
  const e: string[] = [];
  if (pt.schema !== PLAYTEST_SCHEMA) e.push(`playtest.schema must be ${PLAYTEST_SCHEMA}`);
  if (pt.username != null && !USERNAME_RE.test(String(pt.username))) e.push("playtest.username must be 3-16 chars of A-Z a-z 0-9 _");
  if (pt.op != null && typeof pt.op !== "boolean") e.push("playtest.op must be a boolean");
  if (pt.totalSec != null && !intIn(pt.totalSec, 10, PLAYTEST_LIMITS.totalSecMax)) e.push(`playtest.totalSec must be 10-${PLAYTEST_LIMITS.totalSecMax}`);
  if (pt.joinSec != null && !intIn(pt.joinSec, 5, PLAYTEST_LIMITS.joinSecMax)) e.push(`playtest.joinSec must be 5-${PLAYTEST_LIMITS.joinSecMax}`);
  const scs = pt.scenarios;
  if (!Array.isArray(scs) || !scs.length || scs.length > PLAYTEST_LIMITS.scenarios) { e.push(`playtest.scenarios must hold 1-${PLAYTEST_LIMITS.scenarios} scenarios`); return e; }
  const seen = new Set<string>();
  for (const [i, raw2] of scs.entries()) {
    const sc = raw2 as Record<string, unknown> | null;
    const k = `playtest.scenarios[${i}]`;
    if (!sc || typeof sc !== "object") { e.push(`${k} must be an object`); continue; }
    if (!SCENARIO_ID_RE.test(String(sc.id ?? ""))) e.push(`${k}.id must be a test id (T-1, T-2, ...)`);
    if (seen.has(String(sc.id))) e.push(`${k}.id ${sc.id} is listed twice`);
    seen.add(String(sc.id));
    if (sc.title != null && !isStr(sc.title, 500)) e.push(`${k}.title must be 1-500 chars`);
    if (sc.covers != null && (!Array.isArray(sc.covers) || sc.covers.length > 50 || !sc.covers.every((r) => REQ_RE.test(String(r))))) e.push(`${k}.covers must be requirement ids (REQ-n)`);
    if (sc.reset != null && typeof sc.reset !== "boolean") e.push(`${k}.reset must be a boolean`);
    const steps = sc.steps;
    if (!Array.isArray(steps) || !steps.length || steps.length > PLAYTEST_LIMITS.steps) { e.push(`${k}.steps must hold 1-${PLAYTEST_LIMITS.steps} steps`); continue; }
    for (const [j, st] of steps.entries()) e.push(...stepErrors(st, `${k}.steps[${j}]`));
    steps.forEach((st, j) => { if ((st as { kind?: string })?.kind === "join" && j !== 0) e.push(`${k}.steps[${j}]: join must be the first step`); });
    const proves = steps.some((st) => String((st as { kind?: string })?.kind ?? "").startsWith("expect_") || ((st as { kind?: string })?.kind === "server" && (st as { expect?: unknown }).expect));
    if (!proves) e.push(`${k}: a scenario needs at least one expect_* step (otherwise it proves nothing)`);
  }
  return e;
}

/** Can a playtest run on this Minecraft version? (the bot must have been run against it). */
export function playtestVersion(v: string): { ok: true } | { ok: false; reason: string } {
  return PLAYTEST_BOT_VERSIONS.includes(v) ? { ok: true } : { ok: false, reason: `not run: no verified playtest bot for Minecraft ${v} (verified: ${PLAYTEST_BOT_VERSIONS.join(", ")})` };
}

// Cyrus playtest bots (R3): honest verdicts from a Test Flight report that carried a playtest. Pure.
// Rules (never relaxed):
// - a scenario passes only if the bot joined, every step ran and passed, and the server logged no error during it;
// - a requirement is "passed" only if at least one scenario covering it passed and none failed;
// - anything the bot did not run is "not_run"; tests that were never scripted are "not_scripted" / "manual";
// - the label says "playtested" only for scenarios that actually ran, with the counts, never "verified" in general.
import type { TestFlightReport } from "../testflight/types";
import type { PlaytestPlan } from "./plan";
import type { TestCoverage } from "./generate";

export type StepResult = { i: number; kind: string; status: "pass" | "fail" | "not_run"; evidence: string[]; ms: number };
export type ScenarioResult = {
  id: string; title: string | null; covers: string[]; status: "pass" | "fail" | "not_run"; steps: StepResult[]; ms: number;
  /** Server log lines matched while the scenario ran (runner side). */
  logHits?: string[];
  failedBy?: "server_log";
};
/** What the runner stores on report.playtest (runner tf-lite-4). */
export type PlaytestRunResult = {
  schema: 1; username: string; version: string; joined: boolean; joinFailed: boolean; joinMs: number | null; op: boolean;
  bot: { mineflayer: string | null; minecraftProtocol: string | null; lockSha256: string | null };
  scenarios: ScenarioResult[]; notes: string[]; disconnect: { reason: string; kicked?: boolean } | null;
  spawn?: { x: number; y: number; z: number }; messages?: number;
};

/** other_check = proven by the build / scanner / Test Flight boot, not by the bot. */
export type RequirementStatus = "passed" | "failed" | "not_run" | "not_scripted" | "manual" | "other_check";
export type PlaytestVerdict = {
  verdict: "passed" | "failed" | "incomplete" | "not_run";
  /** Customer/admin line. Never claims more than ran. */
  label: string;
  scenarios: { id: string; status: "pass" | "fail" | "not_run"; reason: string | null; covers: string[] }[];
  requirements: { id: string; status: RequirementStatus; by: string[] }[];
  counts: { planned: number; ran: number; passed: number; failed: number; notRun: number };
  bot: PlaytestRunResult["bot"] | null;
};

const VALID = new Set(["pass", "fail", "not_run"]);

function scenarioStatus(sc: ScenarioResult | undefined): "pass" | "fail" | "not_run" {
  if (!sc || !VALID.has(sc.status)) return "not_run";
  const steps = Array.isArray(sc.steps) ? sc.steps : [];
  if (sc.status === "fail" || steps.some((s) => s.status === "fail")) return "fail";
  // a "pass" needs every step to have run with evidence
  if (sc.status === "pass" && steps.length && steps.every((s) => s.status === "pass" && Array.isArray(s.evidence) && s.evidence.some((e) => String(e).trim()))) return "pass";
  return "not_run";
}

function reasonOf(sc: ScenarioResult | undefined, st: "pass" | "fail" | "not_run"): string | null {
  if (!sc) return "did not run";
  if (st === "pass") return null;
  if (sc.failedBy === "server_log" && sc.logHits?.length) return `server logged an error: ${sc.logHits[0]}`;
  const bad = (sc.steps ?? []).find((s) => s.status !== "pass");
  return bad ? `step ${bad.i + 1} (${bad.kind}): ${(bad.evidence ?? []).join("; ").slice(0, 240)}` : "did not run";
}

/** Verdict for one flight. `coverage` (from planFromSpec) adds the tests that never became scenarios. */
export function playtestVerdict(plan: PlaytestPlan, report: TestFlightReport | null, coverage: TestCoverage[] = []): PlaytestVerdict {
  const run = (report as (TestFlightReport & { playtest?: PlaytestRunResult }) | null)?.playtest ?? null;
  const ok = !!report && report.status === "completed" && !!run && run.joined;
  const byId = new Map((run?.scenarios ?? []).map((s) => [s.id, s] as const));
  const scenarios = plan.scenarios.map((p) => {
    const sc = ok ? byId.get(p.id) : undefined;
    const st = scenarioStatus(sc);
    return { id: p.id, status: st, reason: ok ? reasonOf(sc, st) : (run?.notes?.slice(-1)[0] ?? (report?.status === "busy" ? "another Test Flight was running" : "the bot did not run")), covers: p.covers ?? [] };
  });
  const passed = scenarios.filter((s) => s.status === "pass").length;
  const failed = scenarios.filter((s) => s.status === "fail").length;
  const notRun = scenarios.length - passed - failed;
  const reqs = new Map<string, { status: RequirementStatus; by: string[] }>();
  const seen = new Map<string, { st: Set<string>; by: string[] }>();
  for (const s of scenarios) for (const r of s.covers) {
    const e = seen.get(r) ?? { st: new Set<string>(), by: [] };
    e.st.add(s.status); e.by.push(s.id); seen.set(r, e);
  }
  // any covering scenario failed -> failed; else any passed -> passed; else not_run
  for (const [r, e] of seen) reqs.set(r, { status: e.st.has("fail") ? "failed" : e.st.has("pass") ? "passed" : "not_run", by: e.by });
  for (const c of coverage) {
    if (c.status === "scripted" || c.status === "explicit") continue;
    for (const r of c.covers) if (!reqs.has(r)) reqs.set(r, { status: c.status === "manual" ? "manual" : c.status === "other_check" ? "other_check" : "not_scripted", by: [c.testId] });
  }
  const verdict: PlaytestVerdict["verdict"] = !ok ? (run?.joinFailed ? "failed" : "not_run") : failed ? "failed" : notRun ? "incomplete" : "passed";
  const v = report?.version ?? run?.version ?? "?";
  const label = !ok
    ? (run?.joinFailed ? `Playtest failed on Paper ${v}: the bot could not join (${run.disconnect?.reason ?? "kicked"})` : "Playtest not run")
    : `Playtested on Paper ${v}: ${passed} of ${scenarios.length} acceptance check${scenarios.length === 1 ? "" : "s"} passed${failed ? `, ${failed} failed` : ""}${notRun ? `, ${notRun} not run` : ""}`;
  return {
    verdict, label, scenarios,
    requirements: [...reqs.entries()].sort(([a], [b]) => Number(a.slice(4)) - Number(b.slice(4))).map(([id, r]) => ({ id, ...r })),
    counts: { planned: scenarios.length, ran: passed + failed, passed, failed, notRun },
    bot: run?.bot ?? null,
  };
}
// Cyrus playtest bots (R3): run a ModSpec's playtest inside ONE Test Flight on node-2. Server-only (through the
// injectable Test Flight invoker; tests pass a fake). OFF unless CYRUS_PLAYTEST=1 (or `enabled: true` from a caller
// that has its own switch, e.g. a by-hand real run). Not wired into the build path or the gate sweep yet.
import type { ModSpec } from "../engine-core/spec";
import type { TestFlightSpec, TestFlightSummary, TestFlightReport } from "../testflight/types";
import { summarize } from "../testflight/summary";
import { planFromSpec, type GenerateOptions, type TestCoverage } from "./generate";
import { playtestVersion, type PlaytestPlan } from "./plan";
import { playtestVerdict, type PlaytestVerdict } from "./verdict";

export const PLAYTEST_FLAG = "CYRUS_PLAYTEST";
export const playtestEnabled = (env: Record<string, string | undefined> = process.env) => env[PLAYTEST_FLAG] === "1";

export type FlightRunner = (spec: TestFlightSpec) => Promise<{ report: TestFlightReport; summary: TestFlightSummary }>;

export type PlaytestRun =
  | { ran: false; reason: string; plan: PlaytestPlan | null; coverage: TestCoverage[] }
  | { ran: true; plan: PlaytestPlan; coverage: TestCoverage[]; flight: TestFlightSpec; report: TestFlightReport; summary: TestFlightSummary; verdict: PlaytestVerdict };

/** Attach a plan to a boot flight. Validation (incl. the bot version list) happens in validateSpec. */
export function withPlaytest(flight: TestFlightSpec, plan: PlaytestPlan): TestFlightSpec {
  return { ...flight, playtest: plan, timeouts: { ...(flight.timeouts ?? {}), totalSec: Math.min(900, Math.max(flight.timeouts?.totalSec ?? 420, 300 + (plan.totalSec ?? 90) + (plan.joinSec ?? 30))) } };
}

/**
 * spec -> plan -> one flight with the built artifacts -> honest verdict. `flight` carries the version, plugins,
 * datapacks and boot checks (same as the gate's flight); its version must equal the spec's target.
 */
export async function runPlaytest(spec: ModSpec, flight: TestFlightSpec, run: FlightRunner, opts: GenerateOptions & { enabled?: boolean } = {}): Promise<PlaytestRun> {
  const gen = planFromSpec(spec, opts);
  if (!(opts.enabled ?? playtestEnabled())) return { ran: false, reason: `not run: ${PLAYTEST_FLAG} is off`, plan: gen.plan, coverage: gen.coverage };
  if (!gen.plan) return { ran: false, reason: "not run: no acceptance test could be scripted", plan: null, coverage: gen.coverage };
  if (flight.version !== spec.target.version) return { ran: false, reason: `not run: flight is for ${flight.version}, the spec targets ${spec.target.version}`, plan: gen.plan, coverage: gen.coverage };
  const pv = playtestVersion(flight.version);
  if (!pv.ok) return { ran: false, reason: pv.reason, plan: gen.plan, coverage: gen.coverage };
  const tf = withPlaytest(flight, gen.plan);
  const { report } = await run(tf);
  const summary = summarize(tf, report);
  return { ran: true, plan: gen.plan, coverage: gen.coverage, flight: tf, report, summary, verdict: playtestVerdict(gen.plan, report, gen.coverage) };
}
// Cyrus playtest bots (R3): scripted Mineflayer playtests generated from a ModSpec's acceptance tests, run inside a
