export * from "./plan";
export * from "./generate";
export * from "./verdict";
export * from "./flight";
// Cyrus playtest bots (R3): turn a ModSpec's ACCEPTANCE TESTS into a playtest plan. Deterministic, no model call.
// Pure + client-safe.
//
// Source of each scenario, in order:
//   1. an explicit script for the test id (`opts.scripts["T-2"]`, typed steps, e.g. written by the AI author or a
//      designer and validated here) -> "explicit";
//   2. the test's description compiled with the CRITERIA GRAMMAR below -> "scripted";
//   3. otherwise the test is reported "not_scriptable" with the reason. It is never silently dropped or claimed.
// Only `functional` tests become scenarios. `manual` tests stay manual; compile/scan/boot tests are proven by the
// build, the scanner and the Test Flight boot (not by the bot) and are reported as such.
//
// CRITERIA GRAMMAR (what a test description may say; quotes may be "straight" or "curly"):
//   triggers  : `when a player joins` / `on join`            -> join (messages since the bot joined)
//               running `/cmd args` (backticks; or bare /cmd without args) -> the bot player runs the command
//               the console runs `cmd`                         -> console command over RCON
//               holding `item_id` ... right-click(ing)         -> hold the item, then use it
//               after 2 seconds / waits 500 ms                 -> wait
//   outcomes  : says / replies / sees / sends / shows / tells / message "text"  -> expect_chat
//               never / not / no ... "text"                    -> expect_no_chat
//               title "text"                                   -> expect_title
//               gives / receives / has [N | a] `item` | N item [named "Name"]   -> expect_inventory
//               never / not ... gives [N | a] `item`           -> expect_no_item
//               the `speed` effect / the speed effect          -> expect_effect
//               teleports / moves / launches [N blocks]        -> expect_moved
import type { ModSpec, TestPlan } from "../engine-core/spec";
import { PLAYTEST_SCHEMA, validatePlaytestPlan, stepErrors, type PlaytestPlan, type PlaytestScenario, type PlaytestStep } from "./plan";

export type CoverageStatus = "explicit" | "scripted" | "not_scriptable" | "manual" | "other_check";
export type TestCoverage = {
  testId: string;
  kind: TestPlan["kind"];
  covers: string[];
  status: CoverageStatus;
  /** Why it is not a scenario (not_scriptable / manual / other_check), or what the compiler could not use. */
  reason?: string;
  steps?: number;
};

export type GenerateOptions = {
  /** Explicit steps per test id; they win over the compiled description. */
  scripts?: Record<string, PlaytestStep[]>;
  /** Force the bot's operator status (default: on when a description says "as an operator" / "as op"). */
  op?: boolean;
  username?: string;
  totalSec?: number;
};

export type GenerateResult = { plan: PlaytestPlan | null; coverage: TestCoverage[]; problems: string[] };

type Hit = { at: number; end: number; step: PlaytestStep; action: boolean };

const ACTION = new Set(["join", "command", "chat", "server", "wait", "hold", "use_item"]);
const NOT_ITEMS = new Set(["the", "a", "an", "effect", "message", "title", "item", "items", "player", "them", "you", "it", "chat", "reply", "speed"]);
const NEG_BEFORE = /(?:\bnever|\bnot|\bno longer|\bdoesn't|\bdoes not|\bwithout|\bno)\s+(?:\w+\s+){0,3}$/i;

function normalise(s: string): string {
  return s.replace(/[“”„«»]/g, '"').replace(/[‘’]/g, "'").replace(/\s+/g, " ").trim();
}

/** Compile one test description into steps (textual order, actions before the outcomes they cause). */

#!/usr/bin/env node
"use strict";
// Cyrus playtest bot (R3): ONE scripted Mineflayer player that joins a Test Flight server and runs a typed playtest
// plan (playtest-lib.js). Started by runner.js inside the flight's private network namespace, as uid 65534, with a
// heap cap and a hard timeout; it only ever talks to 127.0.0.1 (the server + its RCON). No free-form code is run:
// each step is one of the fixed kinds. Output: JSON lines prefixed "@@PT " on stdout (scenario start/end events,
// then one final result). Usage: node bot.js <script.json> <run marker>
//
// The marker argument is not used here; it puts the flight's -Dnxeon.testflight.run=<id> marker on this process's
// cmdline so the runner's leak scan and exact-PID kills cover the bot too.

const fs = require("fs");
const path = require("path");
const net = require("net");
const L = require("./lib.js");
const P = require("./playtest-lib.js");

const now = () => Date.now();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clip = (s, n = 240) => String(s).replace(/\s+/g, " ").slice(0, n);
const emit = (o) => process.stdout.write("@@PT " + JSON.stringify(o) + "\n");

function rconConnect(port, password, timeoutMs) {
  return new Promise((resolve, reject) => {
    const sock = net.connect({ host: "127.0.0.1", port });
    let buf = Buffer.alloc(0), nextId = 500;
    const waiters = [];
    const timer = setTimeout(() => { sock.destroy(); reject(new Error("rcon connect timeout")); }, timeoutMs);
    sock.on("data", (d) => {
      buf = Buffer.concat([buf, d]);
      const { packets, rest } = L.rconParse(buf);
      buf = rest;
      for (const p of packets) for (const w of [...waiters]) w(p);
    });
    sock.on("error", (e) => { clearTimeout(timer); reject(e); });
    const request = (type, body, maxMs = timeoutMs) => new Promise((res, rej) => {
      const id = nextId++;
      let text = "", got = false, q = null;
      const done = () => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); clearTimeout(q); res(text); };
      const w = (p) => {
        if (p.id === -1 && type === 3) { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); rej(new Error("rcon auth refused")); return; }
        if (p.id !== id) return;
        got = true; text += p.body;
        clearTimeout(q); q = setTimeout(done, type === 3 ? 0 : 250);
      };
      const hard = setTimeout(() => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(q); got ? res(text) : rej(new Error(`rcon timeout after ${maxMs} ms`)); }, maxMs);
      waiters.push(w);
      sock.write(L.rconPacket(id, type, body));
    });
    sock.on("connect", async () => {
      clearTimeout(timer);
      try { await request(3, password); resolve({ command: (c, ms) => request(2, c, ms), close: () => sock.destroy() }); } catch (e) { sock.destroy(); reject(e); }
    });
  });
}

async function main() {
  const script = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
  const plan = script.plan;
  const username = plan.username || P.DEFAULTS.username;
  const totalMs = (plan.totalSec || P.DEFAULTS.totalSec) * 1000;
  const joinMs = (plan.joinSec || P.DEFAULTS.joinSec) * 1000;
  const result = {
    schema: 1, username, version: script.version, joined: false, joinFailed: false, joinMs: null, op: !!plan.op,
    bot: { mineflayer: null, minecraftProtocol: null, lockSha256: script.lockSha256 || null }, scenarios: [], notes: [], disconnect: null,
  };
  const t0 = now();
  // Hard guard: whatever happens, print what we have and exit before the runner's own kill.
  const guard = setTimeout(() => { result.notes.push(`bot hard timeout after ${totalMs + joinMs + 5000} ms`); finish(); }, totalMs + joinMs + 5000);
  let finished = false;
  function finish() {
    if (finished) return;
    finished = true;
    clearTimeout(guard);
    emit({ ev: "result", result });
    setTimeout(() => process.exit(0), 200);
  }

  let mineflayer, Vec3 = null;
  try {
    mineflayer = require(path.join(script.modulesDir, "mineflayer"));
    try { Vec3 = require(path.join(script.modulesDir, "vec3")).Vec3; } catch { /* dig steps then fail with a reason */ }
    result.bot.mineflayer = require(path.join(script.modulesDir, "mineflayer/package.json")).version;
    result.bot.minecraftProtocol = require(path.join(script.modulesDir, "minecraft-protocol/package.json")).version;
  } catch (e) { result.notes.push(`mineflayer not available: ${clip(e.message)}`); return finish(); }

  let rcon = null;
  try { rcon = await rconConnect(script.rconPort, script.rconPassword, 10000); } catch (e) { result.notes.push(`bot RCON unavailable: ${clip(e.message)} (server steps and resets cannot run)`); }

  // ---- join
  const msgs = [], titles = [];
  let ended = null;
  const bot = mineflayer.createBot({
    host: "127.0.0.1", port: script.port, username, version: script.version, auth: "offline",
    hideErrors: true, checkTimeoutInterval: 60000, respawn: true, logErrors: false,
  });
  bot.on("messagestr", (text, position) => msgs.push({ t: now(), text: P.stripColors(String(text)), pos: String(position || "") }));
  bot.on("title", (text, type) => titles.push({ t: now(), text: P.chatText(text), type: String(type || "") }));
  // the world border this client was last told (expect_border): initialize / size / lerp packets
  const border = { size: null, packets: 0 };
  const onBorder = (p) => { const s = p && (p.newDiameter != null ? p.newDiameter : p.diameter != null ? p.diameter : null); if (typeof s === "number") { border.size = s; border.packets++; } };
  for (const n of ["initialize_world_border", "world_border_size", "world_border_lerp_size", "set_border_size", "set_border_lerp_size"]) { try { bot._client.on(n, onBorder); } catch { /* older protocol names */ } }
  bot.on("error", (e) => result.notes.push(`bot error: ${clip(e && e.message)}`));
  bot.on("end", (reason) => { ended = ended || { reason: clip(reason || "end") }; });
  bot.on("kicked", (reason) => { ended = { reason: `kicked: ${clip(P.chatText(reason))}`, kicked: true }; });

  const joined = await new Promise((resolve) => {
    const t = setTimeout(() => resolve(false), joinMs);
    bot.once("spawn", () => { clearTimeout(t); resolve(true); });
    bot.once("end", () => { clearTimeout(t); resolve(false); });
  });
  if (!joined) {
    result.joinFailed = !!(ended && ended.kicked);
    result.disconnect = ended;
    result.notes.push(ended ? `bot could not join: ${ended.reason}` : `bot did not spawn within ${joinMs} ms`);
    try { bot.quit(); } catch { /* not connected */ }
    if (rcon) rcon.close();
    return finish();
  }
  result.joined = true;
  result.joinMs = now() - t0;
  result.spawn = (() => { const p = bot.entity.position; return { x: +p.x.toFixed(2), y: +p.y.toFixed(2), z: +p.z.toFixed(2) }; })();
  await sleep(1000); // let join messages and the first inventory/effect packets arrive

  // movement tracking (reset at every action): max distance from where the bot stood when the action was sent
  const track = { origin: bot.entity.position.clone(), max: 0 };
  bot.on("move", () => { try { track.max = Math.max(track.max, bot.entity.position.distanceTo(track.origin)); } catch { /* no entity */ } });
  const items = () => bot.inventory.items().map((i) => ({ name: i.name, count: i.count, customName: (() => { try { return i.customName; } catch { return null; } })() }));
  const effectNames = () => Object.values(bot.entity.effects || {}).map((e) => {
    const reg = bot.registry.effects && bot.registry.effects[e.id];
    return reg ? reg.name : `id${e.id}`;
  });

  const deadline = t0 + joinMs + totalMs;
  for (const sc of plan.scenarios) {
    const out = { id: sc.id, title: sc.title || null, covers: sc.covers || [], status: "not_run", steps: [], ms: 0 };
    result.scenarios.push(out);
    const notRunRest = (from, why) => { for (let j = from; j < sc.steps.length; j++) out.steps.push({ i: j, kind: sc.steps[j].kind, status: "not_run", evidence: [why], ms: 0 }); };
    if (ended) { notRunRest(0, `skipped: the bot was disconnected (${ended.reason})`); out.status = P.scenarioStatus(out.steps); continue; }
    if (now() > deadline) { notRunRest(0, "skipped: the playtest time budget was used up"); out.status = P.scenarioStatus(out.steps); continue; }
    emit({ ev: "scenario", id: sc.id, phase: "start" });
    const ts = now();
    if (sc.reset !== false && rcon) {
      try { await rcon.command(`clear ${username}`, 5000); await rcon.command(`effect clear ${username}`, 5000); } catch (e) { result.notes.push(`${sc.id}: reset failed: ${clip(e.message)}`); }
      await sleep(400);
    }
    let cursor = msgs.length, tcursor = titles.length;
    track.origin = bot.entity.position.clone(); track.max = 0;
    for (const [j, st] of sc.steps.entries()) {
      const s0 = now();
      const ev = [];
      let status = "fail";
      const since = () => msgs.slice(cursor).map((m) => m.text);
      const poll = async (fn, ms) => { const end = now() + ms; for (;;) { const r = fn(); if (r.ok || now() >= end || ended) return r; await sleep(100); } };
      try {
        if (ended) throw new Error(`bot was disconnected (${ended.reason})`);
        if (P.ACTION_KINDS.has(st.kind)) { cursor = msgs.length; tcursor = titles.length; track.origin = bot.entity.position.clone(); track.max = 0; }
        switch (st.kind) {
          case "join":
            cursor = 0; tcursor = 0; status = "pass";
            ev.push(`joined as ${username} after ${result.joinMs} ms at ${JSON.stringify(result.spawn)}; checking messages since the join (${msgs.length} so far)`);
            break;
          case "command": case "chat":
            bot.chat(st.text); status = "pass"; ev.push(`sent ${st.kind} '${clip(st.text, 120)}'`); await sleep(150);
            break;
          case "server": {
            if (!rcon) { status = "not_run"; ev.push("RCON unavailable; server step not sent"); break; }
            const cmd = P.expandBot(st.command, username);
            const reply = P.stripColors(await rcon.command(cmd, 8000));
            const exp = st.expect ? P.containsAll([reply], st.expect) : { ok: true, missing: [] };
            status = exp.ok ? "pass" : "fail";
            ev.push(`console '${clip(cmd, 120)}' -> ${clip(reply.replace(/\n/g, " | ") || "(empty)", 200)}${exp.ok ? "" : " missing " + JSON.stringify(exp.missing)}`);
            await sleep(150);
            break;
          }
          case "wait": await sleep(st.ms); status = "pass"; ev.push(`waited ${st.ms} ms`); break;
          case "hold": {
            const want = P.bareId(st.item);
            const it = bot.inventory.items().find((i) => i.name === want);
            if (!it) { status = "fail"; ev.push(`no ${want} in the inventory to hold (inventory: ${P.describeInventory(items())})`); break; }
            await bot.equip(it, "hand");
            status = bot.heldItem && bot.heldItem.name === want ? "pass" : "fail";
            ev.push(`held item: ${bot.heldItem ? bot.heldItem.name : "nothing"}`);
            break;
          }
          case "use_item":
            bot.activateItem(); await sleep(150); bot.deactivateItem(); status = "pass";
            ev.push(`right-clicked with ${bot.heldItem ? bot.heldItem.name : "an empty hand"}`);
            break;
          case "dig": {
            // break one block as the player (survival: real dig time with the held tool); the bot must stand within reach
            if (!Vec3) { status = "fail"; ev.push("vec3 module missing"); break; }
            const b = bot.blockAt(new Vec3(st.x, st.y, st.z));
            if (!b || b.name === "air") { status = "fail"; ev.push(`no block at ${st.x} ${st.y} ${st.z} (${b ? b.name : "unloaded"})`); break; }
            const name = b.name;
            try { await Promise.race([bot.dig(b, true), sleep(8000).then(() => { throw new Error("dig timeout after 8000 ms"); })]); } catch (e) { status = "fail"; ev.push(`dig ${name}: ${clip(e.message, 160)}`); break; }
            await sleep(100);
            const after = bot.blockAt(new Vec3(st.x, st.y, st.z));
            status = after && after.name !== name ? "pass" : "fail";
            ev.push(`dug ${name} at ${st.x} ${st.y} ${st.z} with ${bot.heldItem ? bot.heldItem.name : "an empty hand"}; now ${after ? after.name : "unloaded"}`);
            break;
          }
          case "sneak":
            bot.setControlState("sneak", !!st.on); await sleep(200); status = "pass"; ev.push(`sneak ${st.on ? "on" : "off"}`);
            break;
          case "use_on_entity": {
            const want = P.bareId(st.type);
            const me = bot.entity.position;
            const near = Object.values(bot.entities).filter((x) => x !== bot.entity && String(x.name || "").replace(/^minecraft:/, "") === want && x.position.distanceTo(me) <= 6)
              .sort((a, b) => a.position.distanceTo(me) - b.position.distanceTo(me))[0];
            if (!near) { status = "fail"; ev.push(`no ${want} within 6 blocks`); break; }
            await bot.lookAt(near.position.offset(0, (near.height || 1) / 2, 0), true);
            bot.activateEntity(near); await sleep(200); status = "pass";
            ev.push(`right-clicked the ${want} ${near.position.distanceTo(me).toFixed(2)} blocks away with ${bot.heldItem ? bot.heldItem.name : "an empty hand"}`);
            break;
          }
          case "expect_chat": {
            const r = await poll(() => P.containsAll(since(), st.contains), st.withinMs || P.DEFAULTS.withinMs);
            status = r.ok ? "pass" : "fail";
            ev.push(r.ok ? `saw ${JSON.stringify(st.contains)}` : `missing ${JSON.stringify(r.missing)}`, `messages: ${clip(since().join(" | ") || "(none)", 300)}`);
            break;
          }
          case "expect_no_chat": {
            await sleep(st.forMs || P.DEFAULTS.forMs);
            const r = P.containsAny(since(), st.contains);
            status = r.ok ? "pass" : "fail";
            ev.push(r.ok ? `none of ${JSON.stringify(st.contains)} in ${since().length} message(s)` : `saw forbidden ${JSON.stringify(r.found)}`, `messages: ${clip(since().join(" | ") || "(none)", 300)}`);
            break;
          }
          case "expect_inventory": {
            const r = await poll(() => P.inventoryMatch(items(), st), st.withinMs || P.DEFAULTS.withinMs);
            status = r.ok ? "pass" : "fail";
            ev.push(`${r.ok ? "has" : "LACKS"} ${r.want}x ${P.bareId(st.item)}${st.name ? ` named "${st.name}"` : ""} (matching ${r.total}, same id ${r.sameId})`, `inventory: ${P.describeInventory(items())}`);
            break;
          }
          case "expect_no_item": {
            await sleep(st.forMs || P.DEFAULTS.forMs);
            const r = P.inventoryMatch(items(), { item: st.item, count: 1 });
            status = r.ok ? "fail" : "pass";
            ev.push(`${P.bareId(st.item)} in inventory: ${r.total}`, `inventory: ${P.describeInventory(items())}`);
            break;
          }
          case "expect_effect": {
            const want = P.normEffect(st.effect);
            const r = await poll(() => ({ ok: effectNames().some((n) => P.normEffect(n) === want) }), st.withinMs || P.DEFAULTS.withinMs);
            status = r.ok ? "pass" : "fail";
            ev.push(`${r.ok ? "has" : "LACKS"} effect ${st.effect}; active: ${effectNames().join(", ") || "none"}`);
            break;
          }
          case "expect_entity": {
            const want = P.bareId(st.type);
            const seen = () => Object.values(bot.entities).filter((x) => x !== bot.entity && String(x.name || "").replace(/^minecraft:/, "") === want && x.position.distanceTo(bot.entity.position) <= 16).length;
            const r = await poll(() => ({ ok: st.none ? seen() === 0 : seen() >= 1 }), st.withinMs || P.DEFAULTS.withinMs);
            status = r.ok ? "pass" : "fail";
            ev.push(`this client sees ${seen()} ${want} within 16 blocks (want ${st.none ? "none" : "at least 1"})`);
            break;
          }
          case "expect_border": {
            const fits = () => border.size != null && (st.minSize == null || border.size >= st.minSize) && (st.maxSize == null || border.size <= st.maxSize);
            const r = await poll(() => ({ ok: fits() }), st.withinMs || P.DEFAULTS.withinMs);
            status = r.ok ? "pass" : "fail";
            ev.push(`this client's world border: ${border.size == null ? "never sent" : border.size} (${border.packets} border packet(s)); want ${st.minSize != null ? `>= ${st.minSize} ` : ""}${st.maxSize != null ? `<= ${st.maxSize}` : ""}`);
            break;
          }
          case "expect_time": {
            const tod = () => (bot.time && typeof bot.time.timeOfDay === "number" ? ((bot.time.timeOfDay % 24000) + 24000) % 24000 : null);
            const r = await poll(() => ({ ok: tod() != null && tod() >= st.from && tod() <= st.to }), st.withinMs || P.DEFAULTS.withinMs);
            status = r.ok ? "pass" : "fail";
            ev.push(`this client's time of day: ${tod()} (want ${st.from}-${st.to})`);
            break;
          }
          case "expect_title": {
            const r = await poll(() => P.containsAll(titles.slice(tcursor).map((x) => x.text), st.contains), st.withinMs || P.DEFAULTS.withinMs);
            status = r.ok ? "pass" : "fail";
            ev.push(r.ok ? `title/subtitle showed ${JSON.stringify(st.contains)}` : `missing ${JSON.stringify(r.missing)}`, `titles: ${clip(titles.slice(tcursor).map((x) => `${x.type}:${x.text}`).join(" | ") || "(none)", 200)}`);
            break;
          }
          case "expect_moved": {
            const min = st.minBlocks || 1;
            const r = await poll(() => ({ ok: track.max >= min }), st.withinMs || P.DEFAULTS.withinMs);
            status = r.ok ? "pass" : "fail";
            ev.push(`moved up to ${track.max.toFixed(2)} blocks from where the last action was sent (need ${min})`);
            break;
          }
          default: status = "not_run"; ev.push(`unknown step kind ${st.kind}`);
        }
      } catch (e) {
        status = "fail";
        ev.push(`error: ${clip(e && e.message)}`);
      }
      out.steps.push({ i: j, kind: st.kind, status, evidence: ev, ms: now() - s0 });
      if (status !== "pass") { notRunRest(j + 1, "skipped: an earlier step did not pass"); break; }
      if (now() > deadline) { notRunRest(j + 1, "skipped: the playtest time budget was used up"); break; }
    }
    out.status = P.scenarioStatus(out.steps);
    out.ms = now() - ts;
    emit({ ev: "scenario", id: sc.id, phase: "end", status: out.status });
  }
  result.disconnect = ended;
  result.messages = msgs.length;
  try { bot.quit("playtest done"); } catch { /* gone */ }
  if (rcon) rcon.close();
  await sleep(300);
  finish();
}

main().catch((e) => { emit({ ev: "result", result: { schema: 1, joined: false, joinFailed: false, scenarios: [], notes: [`bot crashed: ${clip(e && (e.stack || e.message), 600)}`] } }); setTimeout(() => process.exit(0), 200); });

