import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.NamespacedKey;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;

/**
 * Component designer-command v1: the one command of a designer mod, declared in plugin.yml (no Brigadier):
 *   /<mod> give <item> [player] [count]   (permission <ns>.give, operators by default)
 *   /<mod> list | params [item]            (permission <ns>.command)
 *   /<mod> reload                          (permission <ns>.reload): config.yml with migration + clamping
 * Console can use every subcommand (give needs a player name there).
 */
public final class DesignCommand implements CommandExecutor, TabCompleter {
    private static final List<String> SUBS = List.of("give", "list", "params", "reload");
    private final Designer d;
    private final String label;

    DesignCommand(Designer d, String label) { this.d = d; this.label = label; }

    private static void say(CommandSender s, String text, NamedTextColor color) { s.sendMessage(Component.text(text, color)); }

    private boolean allowed(CommandSender s, String node) {
        if (s.hasPermission(d.namespace() + "." + node)) return true;
        say(s, "You don't have permission for that.", NamedTextColor.RED);
        return false;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String used, String[] args) {
        if (args.length == 0) {
            List<String> ids = new ArrayList<>();
            for (DesignItem i : d.items()) ids.add(i.id());
            say(sender, d.plugin().getName() + " items: " + String.join(", ", ids) + ". Use /" + label + " give <item> [player] [count], /" + label + " list, /" + label + " params, /" + label + " reload", NamedTextColor.GOLD);
            return true;
        }
        switch (args[0].toLowerCase(Locale.ROOT)) {
            case "give" -> give(sender, args);
            case "list" -> list(sender);
            case "params" -> params(sender, args);
            case "reload" -> {
                if (!allowed(sender, "reload")) return true;
                List<String> notes = d.reload();
                say(sender, d.plugin().getName() + " config reloaded" + (notes.isEmpty() ? "" : " (" + notes.size() + " note" + (notes.size() == 1 ? "" : "s") + ")"), NamedTextColor.GREEN);
                for (String n : notes) say(sender, "- " + n, NamedTextColor.YELLOW);
            }
            default -> say(sender, "Unknown subcommand. Use /" + label + " give, list, params or reload.", NamedTextColor.RED);
        }
        return true;
    }

    private void give(CommandSender sender, String[] args) {
        if (!allowed(sender, "give")) return;
        if (args.length < 2) { say(sender, "Usage: /" + label + " give <item> [player] [count]", NamedTextColor.RED); return; }
        DesignItem item = d.item(args[1].toLowerCase(Locale.ROOT));
        if (item == null) { say(sender, "Unknown item " + args[1] + ".", NamedTextColor.RED); return; }
        Player target;
        if (args.length >= 3) {
            target = Bukkit.getPlayerExact(args[2]);
            if (target == null) { say(sender, "Player " + args[2] + " is not online.", NamedTextColor.RED); return; }
        } else if (sender instanceof Player p) target = p;
        else { say(sender, "Usage from the console: /" + label + " give <item> <player> [count]", NamedTextColor.RED); return; }
        int count = 1;
        if (args.length >= 4) {
            try { count = Math.max(1, Math.min(64, Integer.parseInt(args[3]))); }
            catch (NumberFormatException e) { say(sender, "Count must be a number from 1 to 64.", NamedTextColor.RED); return; }
        }
        for (int i = 0; i < count; i++) for (ItemStack left : target.getInventory().addItem(item.create()).values()) target.getWorld().dropItemNaturally(target.getLocation(), left);
        say(sender, "Gave " + count + " x " + item.id() + " to " + target.getName() + ".", NamedTextColor.GREEN);
    }

    private void list(CommandSender sender) {
        if (!allowed(sender, "command")) return;
        for (DesignItem i : d.items()) {
            ItemStack s = i.create();
            boolean identity = d.identity().is(s, i.id());
            boolean recipe = Bukkit.getRecipe(new NamespacedKey(d.namespace(), i.id())) != null;
            say(sender, i.id() + ": identity=" + (identity ? "ok" : "MISSING") + " material=" + s.getType().getKey().getKey() + " abilities=" + i.abilities().size() + " recipe=" + (recipe ? "registered" : "none"), identity ? NamedTextColor.AQUA : NamedTextColor.RED);
        }
    }

    private void params(CommandSender sender, String[] args) {
        if (!allowed(sender, "command")) return;
        List<String> out = new ArrayList<>();
        for (DesignItem i : d.items()) if (args.length < 2 || i.id().equals(args[1].toLowerCase(Locale.ROOT))) i.describe(out);
        if (out.isEmpty()) say(sender, "No parameters.", NamedTextColor.GRAY);
        for (String line : out) say(sender, line, NamedTextColor.AQUA);
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String used, String[] args) {
        List<String> out = new ArrayList<>();
        String last = args.length == 0 ? "" : args[args.length - 1].toLowerCase(Locale.ROOT);
        if (args.length <= 1) { for (String s : SUBS) if (s.startsWith(last)) out.add(s); }
        else if (args.length == 2 && (args[0].equalsIgnoreCase("give") || args[0].equalsIgnoreCase("params"))) { for (DesignItem i : d.items()) if (i.id().startsWith(last)) out.add(i.id()); }
        else if (args.length == 3 && args[0].equalsIgnoreCase("give")) { for (Player p : Bukkit.getOnlinePlayers()) if (p.getName().toLowerCase(Locale.ROOT).startsWith(last)) out.add(p.getName()); }
        return out;
    }
}
`;

