  z.strictObject({ type: z.literal("join") }),
  z.strictObject({ type: z.literal("death") }),
  z.strictObject({ type: z.literal("item_consume") }),
  /** Hold sneak (with the item in the main hand) to charge, then release: right-click while still sneaking, or stop sneaking. */
