  /** Technique (CYRUS_MC_TECHNIQUES): the holder breaks a block with this item in the main hand (a break no other plugin cancelled). Optional filter: block groups and/or vanilla block ids. The aim point is the broken block's centre; there is no target entity. */
  z.strictObject({ type: z.literal("break_block"), blocks: z.array(z.enum(BLOCK_GROUPS)).min(1).max(2).optional(), types: z.array(VanillaRef).min(1).max(16).optional() }),
]);
export type Trigger = z.infer<typeof TriggerSchema>;

// -------------------------------------------------------------------------------------------------------- conditions
const Neg = { negate: z.boolean().optional() };
const ConditionSchema = z.discriminatedUnion("type", [
  /** Another ability's cooldown (own ability: automatic when cooldownTicks is set). */
  z.strictObject({ type: z.literal("cooldown_ready"), ability: Key.optional(), ...Neg }),
  /** Permission `<namespace>.<node>`, declared in the item's permissions. */
  z.strictObject({ type: z.literal("has_permission"), node: z.string().regex(/^[a-z0-9_]+(\.[a-z0-9_]+){0,3}$/), ...Neg }),
  z.strictObject({ type: z.literal("target_is"), kinds: z.array(z.enum(TARGET_KINDS)).max(4).optional(), types: z.array(VanillaRef).min(1).max(16).optional(), ...Neg }),
  z.strictObject({ type: z.literal("world_in"), worlds: z.array(z.string().regex(/^[A-Za-z0-9_./-]{1,64}$/)).min(1).max(8), ...Neg }),
  z.strictObject({ type: z.literal("health_below"), subject: z.enum(["self", "target"]), fraction: capNum("healthFraction"), ...Neg }),
  z.strictObject({ type: z.literal("health_above"), subject: z.enum(["self", "target"]), fraction: capNum("healthFraction"), ...Neg }),
  /** The given design item (this mod) is in that slot. */
  z.strictObject({ type: z.literal("item_identity"), slot: z.enum(["main_hand", "off_hand"]), item: Key, ...Neg }),
  z.strictObject({ type: z.literal("sneaking"), ...Neg }),
  z.strictObject({ type: z.literal("charges_available"), ability: Key.optional(), amount: capInt("chargeCost"), ...Neg }),
  /** Seeded random (java.util.Random with general.random_seed): the TS simulator draws the same sequence. */
  z.strictObject({ type: z.literal("random_chance"), chance: capNum("chance"), ...Neg }),
  /** World time in ticks (0 = sunrise, 6000 noon, 13000 night, 18000 midnight); from > to wraps over midnight. */
  z.strictObject({ type: z.literal("time_of_day"), from: capInt("timeOfDay"), to: capInt("timeOfDay"), ...Neg }),
]);
export type Condition = z.infer<typeof ConditionSchema>;
export type ConditionType = Condition["type"];
export const CONDITION_TYPES = ConditionSchema.options.map((o) => o.shape.type.value) as ConditionType[];

// ----------------------------------------------------------------------------------------------------------- actions
const Who = z.enum(["self", "target"]);
