async function stagePlaytest({ ctx, spec, C, out, lines, up, port, rconPort, rconPassword, matchers, ignores, notes }) {
  const chk = C.playtest;
  const plan = spec.playtest;
  if (!up) { chk.evidence.push("server not up; the playtest bot did not run"); return; }
  if (ctx.botError) { chk.evidence.push(`playtest bot unavailable: ${ctx.botError}`); return; }
  if (!PT.BOT_VERSIONS.includes(spec.version)) { chk.evidence.push(`no verified playtest bot for Minecraft ${spec.version} (verified: ${PT.BOT_VERSIONS.join(", ")})`); return; }
  const scriptPath = path.join(ctx.runDir, "tmp", "playtest.json");
  fs.writeFileSync(scriptPath, JSON.stringify({ port, rconPort, rconPassword, version: spec.version, plan, modulesDir: ctx.bot.modulesDir, lockSha256: ctx.bot.lockSha }), { mode: 0o600 });
  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, scriptPath]);
  const limitMs = ((plan.totalSec || PT.DEFAULTS.totalSec) + (plan.joinSec || PT.DEFAULTS.joinSec) + 20) * 1000;
  const fromLine = lines.length;
  const spans = {};
  let result = null, partial = "", stderr = "";
  const child = spawn("nice", ["-n", "10", "setpriv", `--reuid=${RUN_UID}`, `--regid=${RUN_UID}`, "--clear-groups", "--no-new-privs", "--",
    process.execPath, "--max-old-space-size=256", path.join(__dirname, "bot.js"), scriptPath, ctx.marker],
    { cwd: path.join(ctx.runDir, "tmp"), stdio: ["ignore", "pipe", "pipe"], env: { PATH: "/usr/bin:/bin", HOME: path.join(ctx.runDir, "tmp"), LANG: "C.UTF-8" } });
  const pid = child.pid;
  child.stdout.on("data", (d) => {
    const parts = (partial + d.toString("utf8")).split("\n");
    partial = parts.pop();
    for (const p of parts) {
      if (!p.startsWith("@@PT ")) continue;
      let ev; try { ev = JSON.parse(p.slice(5)); } catch { continue; }
      if (ev.ev === "scenario" && ev.phase === "start") spans[ev.id] = { from: lines.length, to: null };
      if (ev.ev === "scenario" && ev.phase === "end" && spans[ev.id]) spans[ev.id].to = lines.length;
      if (ev.ev === "result") result = ev.result;
    }
  });
  child.stderr.on("data", (d) => { if (stderr.length < 4000) stderr += d.toString("utf8"); });
  const exitP = new Promise((r) => child.on("exit", (code, sig) => r({ code, sig })));
  const ex = await Promise.race([exitP, sleep(limitMs).then(() => null)]);
  if (!ex) {
    if (killExact(pid, ctx.marker)) chk.evidence.push(`bot pid ${pid} over its ${limitMs} ms limit -> SIGKILL`);
    await Promise.race([exitP, sleep(3000)]);
  }
  await sleep(500); // let the server log the disconnect
  if (!result) { chk.evidence.push(`the bot produced no result (exit ${ex ? ex.code : "killed"})${stderr ? ": " + clip(stderr, 300) : ""}`); return; }
  // Server-side errors while each scenario ran.
  const { hits } = L.matchLogDetailed(lines, matchers, ignores, fromLine, lines.length);
  for (const sc of result.scenarios || []) {
    const sp = spans[sc.id];
    if (!sp) continue;
    const mine = hits.filter((h) => h.line - 1 >= sp.from && h.line - 1 < (sp.to == null ? lines.length : sp.to));
    if (mine.length) {
      sc.logHits = mine.slice(0, 6).map((h) => `L${h.line} [${h.matcher}] ${clip(h.text, 200)}`);
      if (sc.status === "pass") { sc.status = "fail"; sc.failedBy = "server_log"; }
    }
  }
  const outside = hits.filter((h) => !Object.values(spans).some((sp) => h.line - 1 >= sp.from && h.line - 1 < (sp.to == null ? lines.length : sp.to)));
  chk.status = PT.playtestCheckStatus(result);
  if (outside.length && chk.status === "pass") chk.status = "fail";
  const b = result.bot || {};
  chk.evidence.push(result.joined
    ? `bot ${result.username} joined Paper ${spec.version} in ${result.joinMs} ms (mineflayer ${b.mineflayer}, minecraft-protocol ${b.minecraftProtocol}, op ${result.op})`
    : `bot did not join: ${(result.notes || []).slice(-1)[0] || "no detail"}`);
  for (const sc of result.scenarios || []) {
    const bad = (sc.steps || []).find((s) => s.status !== "pass");
    chk.evidence.push(`${sc.id} ${sc.status.toUpperCase()} (${(sc.steps || []).filter((s) => s.status === "pass").length}/${(sc.steps || []).length} steps, ${sc.ms} ms)${bad ? ` at step ${bad.i + 1} ${bad.kind}: ${clip(bad.evidence.join("; "), 220)}` : ""}${sc.logHits ? ` server log: ${sc.logHits[0]}` : ""}`);
  }
  if (outside.length) chk.evidence.push(...outside.slice(0, 4).map((h) => `server log during the playtest (no scenario): L${h.line} [${h.matcher}] ${clip(h.text, 200)}`));
  for (const n of (result.notes || []).slice(0, 6)) notes.push(`playtest: ${clip(n, 300)}`);
  // Bound the stored result: evidence lines are already clipped by the bot; cap counts.
  for (const sc of result.scenarios || []) for (const st of sc.steps || []) st.evidence = (st.evidence || []).slice(0, 4);
  out.playtest = result;
}

/**
 * STRESS (tf-lite-5). Baseline samples, then for `seconds`: RCON summons of passive mobs (tagged nxstress), forced
 * chunk loads on a spiral, the mod's commands once, and (verified bot versions only) the stress bot placing/breaking
 * blocks and teleporting. A second RCON connection carries the load so the sampler is never queued behind it. Every
 * sample: real TPS = delta `time query gametime` / delta wall clock (a reply slower than stallSec = a stall), Paper MSPT,
 * entity count, RSS. Afterwards the load is removed (kill non-players, forceload remove all) before the clean stop.
 */
